window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q12"]=window.__LIBQ["the-gioi-hoan-my"]["q12"]||{};window.__LIBQ["the-gioi-hoan-my"]["q12"]["artifacts"]={"updatedAt":"2026-07-25","count":96,"artifacts":[{"id":"hoang-huyet-phong-an-trong-da-thuy-tinh","name":"Hoàng Huyết phong ấn trong đá thủy tinh","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chân huyết phong ấn","phamCap":"","soHuu":["Thạch Hạo","Nguyên Phong"],"trangThai":"Được dùng làm vật cược","blurb":"Bốn khối thủy tinh trong suốt phong ấn Hoàng Huyết, được Thạch Hạo trưng ra làm điều kiện cược chiến. Nguyên Phong muốn đoạt chúng và sau đó được người khác cho mượn Hoàng Huyết để chuẩn bị tái chiến.","detail":"Các khối thủy tinh có vẻ ngoài trong suốt như kim cương máu và tỏa xích hà thần thánh. Chúng vừa là tài nguyên được các đệ tử tranh đoạt, vừa trở thành vật cược trong mâu thuẫn giữa Thạch Hạo và Nguyên Phong.","phanLoaiPhu":"Chân huyết và vật phẩm tu luyện","hinhDang":"Các khối thủy tinh trong suốt như kim cương máu","dacDiem":"Thủy tinh trong suốt tỏa xích hà thần thánh.","congNang":["Được dùng làm tiền cược và tài nguyên tu luyện bị các đệ tử tranh đoạt."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1102","denChuong":"","cachCoDuoc":"Nhận các khối thủy tinh từ chỗ Thích Lâm.","trangThai":"Đang giữ bốn khối làm vật cược."},{"ten":"Nguyên Phong","tuChuong":"@c1102","denChuong":"","cachCoDuoc":"Được một số người cho mượn Hoàng Huyết để chuẩn bị tái chiến.","trangThai":"Được cho mượn."}],"capNhatToi":"@c1102","tabs":{"tienTrinh":[{"chuong":"@c1102","loai":"xuất hiện","importance":"normal","giaiDoan":"Trở thành vật cược","text":"Thạch Hạo trưng ra bốn khối thủy tinh chứa Hoàng Huyết, khiến Nguyên Phong tìm cách cưỡng ép cược chiến và sau đó vay Hoàng Huyết để chuẩn bị tái đấu.","anchor":"mấy khối thủy tinh lấy ra, dường như kim cương máu giống như trong suốt"}]},"nguon":["@c1102"]},{"id":"hoang-kim-cu-thuyen","name":"Hoàng kim cự thuyền","cn":"","aliases":["Chiến thuyền hoàng kim"],"category":"phap-bao","categoryLabel":"Chiến hạm vận chuyển","phamCap":"","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Đang vận hành","blurb":"Chiến hạm khổng lồ của Thiên Thần Thư Viện, dùng để đưa đông đảo người tham gia tới tiên gia chiến trường. Thân thuyền có quy mô tương đương một hòn đảo lớn.","detail":"Hoàng kim cự thuyền có boong đủ sức chứa đông đảo đệ tử và đưa họ rời thư viện, vượt qua vùng sao trời để tiến về chiến trường cổ.","phanLoaiPhu":"Chiến hạm vận chuyển","hinhDang":"Khổng lồ như một hòn đảo lớn","dacDiem":"Có thân thuyền và boong rộng đủ chứa đông đảo người tham gia hành trình.","congNang":["Đưa người của Thiên Thần Thư Viện tới tiên gia chiến trường."],"chuHienThoi":"Thiên Thần Thư Viện","chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1102","denChuong":"","cachCoDuoc":"","trangThai":"Dùng để vận chuyển đoàn người tới chiến trường."}],"capNhatToi":"@c1102","tabs":{"tienTrinh":[{"chuong":"@c1102","loai":"dùng","importance":"normal","giaiDoan":"Khởi hành tới chiến trường","text":"Hoàng kim cự thuyền chở đoàn người của Thiên Thần Thư Viện rời đi và tiến về tiên gia chiến trường.","anchor":"nó quá mức khổng lồ, có thể so với một toà to lớn hòn đảo"}]},"nguon":["@c1102"]},{"id":"cot-phu-bao-menh","name":"Cốt phù bảo mệnh","cn":"","aliases":["Cốt phù bảo mệnh của Thiên Thần Thư Viện","Bảo mệnh cốt phù của thư viện"],"category":"phap-bao","categoryLabel":"Phù bảo mệnh","phanLoaiPhu":"Cốt phù","phamCap":"Không rõ","soHuu":["Đệ tử chính thức của Thiên Thần thư viện"],"trangThai":"Được phân phát cho đệ tử chính thức","blurb":"Vật bảo mệnh được các trưởng lão Thiên Thần thư viện phân phát trước khi đoàn người thăm dò Tiên gia chiến trường. Số lượng cốt phù có hạn và Thạch Hạo không được cấp vì không phải đệ tử chính thức.","detail":"Cốt phù được dành riêng cho đệ tử chính thức tham gia thí luyện. Vương Hi từng xin thêm một tấm nhằm giúp Thạch Hạo nhưng bị từ chối vì số lượng hữu hạn.","congNang":["Bảo mệnh cho người mang khi thăm dò Tiên gia chiến trường."],"dacDiem":"Số lượng hữu hạn và chỉ được cấp cho đệ tử chính thức.","chuHienThoi":"Các đệ tử chính thức của Thiên Thần thư viện","chuSoHuu":[{"ten":"Đệ tử chính thức của Thiên Thần thư viện","tuChuong":"@c1103","denChuong":"","cachCoDuoc":"Được các trưởng lão phân phát trước khi thăm dò chiến trường","trangThai":"dang-co"}],"capNhatToi":"@c1103","tabs":{"tienTrinh":[{"chuong":"@c1103","loai":"xuất hiện","importance":"normal","giaiDoan":"Phân phát trước thí luyện","text":"Các trưởng lão phân phát cốt phù cho đệ tử chính thức trước khi họ tiến vào Tiên gia chiến trường, nhưng từ chối cấp thêm cho Thạch Hạo.","anchor":"Mấy vị trưởng lão từng cái từng cái phân phát cốt phù, bất quá giới hạn ở đệ tử chính thức","phamCap":"Không rõ"}]},"nguon":["@c1103"]},{"id":"dai-te-dan-co-loi-vao-tien-gia-chien-truong","name":"Đại tế đàn cổ","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Tế đàn truyền tống","phanLoaiPhu":"Một trong bốn đại tế đàn thời xưa","phamCap":"Không rõ","soHuu":[],"trangThai":"Tàn tạ, chỉ kích hoạt được một phần","blurb":"Một trong bốn đại tế đàn thời xưa, nằm trong cổ địa dẫn tới Tiên gia chiến trường. Sau khi nhận bảo huyết và tọa độ, tế đàn mở đường hầm không gian cho chiến thuyền vượt qua khoảng cách vũ trụ cực xa.","detail":"Đại tế đàn có cùng loại với tế đàn đã biến mất trong Hắc Uyên ở Tiên Cổ. Nó có thể khiến chiến thuyền khổng lồ trở nên nhỏ như hạt bụi, nhưng các trưởng lão phải gần như cạn sức và hiến tế nhiều loại bảo huyết mới kích hoạt được một phần hoa văn; công dụng nguyên thủy của tế đàn chưa được khôi phục.","nguonGoc":"Một trong bốn đại tế đàn thời xưa.","congNang":["Mở đường hầm không gian theo tọa độ đã xác định.","Đưa chiến thuyền vượt qua khoảng cách tương đương hàng trăm nghìn tinh hệ.","Thu nhỏ chiến thuyền khổng lồ như hạt bụi khi đáp xuống bề mặt tế đàn."],"uyLuc":"Có thể mở một hành trình vượt khoảng cách vũ trụ mà người trong đoàn không thể tự hoàn thành trong suốt đời mình.","dacDiem":"Tế đàn đã tàn tạ, chỉ một phần hoa văn có thể được kích hoạt bằng bảo huyết và cổ pháp.","capNhatToi":"@c1103","tabs":{"tienTrinh":[{"chuong":"@c1103","loai":"dùng","importance":"normal","giaiDoan":"Mở đường tới chiến trường","text":"Các trưởng lão hiến tế bảo huyết, định tọa độ và kích hoạt một phần đại tế đàn để mở đường hầm không gian đưa chiến thuyền tới Tiên gia chiến trường.","anchor":"Xưa nay tứ đại tế đàn một trong, cùng ba ngàn Đạo Châu biến mất ở Tiên Cổ Hắc Uyên bên trong tế đàn như thế","phamCap":"Không rõ"}]},"nguon":["@c1103"]},{"id":"chien-mau-hoang-kim","name":"Chiến mâu Hoàng Kim","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí","phanLoaiPhu":"Bí bảo công kích","phamCap":"Không rõ","soHuu":["Nguyên Phong"],"trangThai":"Bị phá hủy","blurb":"Chiến mâu Hoàng Kim là binh khí của Nguyên Phong, được chế tạo từ thần liệu hiếm. Khi được dùng để đón đỡ quyền của Thạch Hạo, chiến mâu bị đánh nổ hoàn toàn, khiến Nguyên Phong thổ huyết.","detail":"Nguyên Phong từng lấy Chiến mâu Hoàng Kim làm binh khí công kích và đón đỡ đòn đánh. Khi được vận dụng, chiến mâu có thể khiến hư không sụp đổ, tạo ra những vết nứt kéo dài vài dặm. Tuy nhiên, trong lần đối đầu với Thạch Hạo, cả lưỡi mâu lẫn cán dài đều bị một quyền phá nát hoàn toàn; lực quyền còn truyền qua pháp khí, khiến Nguyên Phong thổ huyết. @c1105","uyLuc":"Khi được vận dụng, chiến mâu có thể khiến hư không sụp đổ và tạo ra những vết nứt kéo dài vài dặm.","congNang":["Dùng làm binh khí công kích và đón đỡ đòn đánh.","Khi được vận dụng, có thể khiến hư không sụp đổ và tạo ra những vết nứt kéo dài vài dặm."],"chuHienThoi":"Nguyên Phong","chuSoHuu":[{"ten":"Nguyên Phong","tuChuong":"@c1105","denChuong":"@c1105","cachCoDuoc":"Không rõ","trangThai":"Đã bị phá hủy"}],"capNhatToi":"@c1105","tabs":{"tienTrinh":[{"chuong":"@c1105","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Chiến mâu được Nguyên Phong dùng đỡ quyền nhưng bị Thạch Hạo đánh nổ hoàn toàn.","phamCap":"Không rõ","anchor":"Sau một khắc, chỉnh cái chiến mâu Hoàng Kim nổ tung"}]},"nguon":["@c1105"],"dacDiem":"Được chế tạo từ thần liệu hiếm; sau khi đỡ một quyền của Thạch Hạo, chiến mâu bị đánh nổ hoàn toàn. @c1105"},{"id":"manh-mai-rua-chi-ton","name":"Mảnh mai rùa Chí Tôn","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp khí phòng ngự","phanLoaiPhu":"Mảnh mai rùa","phamCap":"Không rõ","soHuu":["Nguyên Phong"],"trangThai":"Bị đâm thủng","blurb":"Mảnh mai rùa Chí Tôn là bảo cụ phòng ngự mạnh nhất của Nguyên Phong, tương truyền do Chí Tôn để lại. Nó có thể hóa thành tấm khiên hộ thân, nhưng từng bị Đại La Tiên Kiếm thai đánh bật và đâm thủng.","detail":"Tương truyền đây là một mảnh mai rùa do Chí Tôn để lại, về sau trở thành bảo cụ phòng ngự mạnh nhất của Nguyên Phong. Mảnh mai rùa có thể hóa thành tấm khiên bảo vệ người sử dụng và được cho là đủ sức ngăn cản tu sĩ cấp Thiên Thần. Khi Nguyên Phong dùng nó hộ thân, Đại La Tiên Kiếm thai đã đánh bật rồi đâm thủng mảnh mai rùa, khiến bề mặt xuất hiện các vết nứt tiếp tục mở rộng. @c1105","nguonGoc":"Tương truyền là mảnh mai rùa do Chí Tôn để lại.","uyLuc":"Năng lực phòng ngự được cho là đủ để ngăn cản tu sĩ cấp Thiên Thần, song đã bị Đại La Tiên Kiếm thai đánh bật và đâm thủng. @c1105","congNang":["Hóa thành tấm khiên để bảo vệ người sử dụng. @c1105"],"chuHienThoi":"Nguyên Phong","chuSoHuu":[{"ten":"Nguyên Phong","tuChuong":"@c1105","denChuong":"@c1105","cachCoDuoc":"Không rõ","trangThai":"Đã bị đâm thủng"}],"capNhatToi":"@c1105","tabs":{"tienTrinh":[{"chuong":"@c1105","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị kiếm thai xuyên thủng","text":"Mảnh mai rùa được Nguyên Phong dùng làm khiên nhưng bị Đại La Tiên Kiếm thai đánh bật rồi đâm thủng.","phamCap":"Không rõ","anchor":"Thạch Hạo cầm trong tay kiếm thai, đem mai rùa đâm thủng"}]},"nguon":["@c1105"],"dacDiem":"Một mảnh mai rùa tương truyền do Chí Tôn để lại; sau khi bị Đại La Tiên Kiếm thai đâm thủng, bề mặt xuất hiện các vết nứt tiếp tục mở rộng. @c1105"},{"id":"dai-la-tien-kiem-thai","name":"Đại La Tiên Kiếm thai","cn":"","aliases":["Đại La Tiên Kiếm"],"category":"phap-bao","categoryLabel":"Kiếm thai","phanLoaiPhu":"Kiếm","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo sở hữu","blurb":"Kiếm thai của Thạch Hạo, được dùng để phá bảo cụ phòng ngự mạnh nhất của Nguyên Phong. (+) Tiên kiếm được Thạch Hạo dùng trong cuộc truy sát sinh linh lông đỏ. [CAN-SOAT-GOP]","detail":"Thạch Hạo lấy kiếm thai ra trong thời gian rất ngắn, nhẹ nhàng đánh bật rồi đâm xuyên mảnh mai rùa Chí Tôn. Kiếm khí từ nó còn xuyên thủng bàn tay Nguyên Phong trước khi thân kiếm tới gần.","uyLuc":"Có thể đâm thủng mảnh mai rùa được truyền là do Chí Tôn để lại.","congNang":["Phá vỡ pháp khí phòng ngự.","Phóng kiếm khí xuyên thủng mục tiêu từ xa."],"chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1105","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1105","tabs":{"tienTrinh":[{"chuong":"@c1105","loai":"dùng","importance":"normal","giaiDoan":"Phá mảnh mai rùa","text":"Thạch Hạo dùng Đại La Tiên Kiếm thai đánh bật và đâm thủng mảnh mai rùa Chí Tôn của Nguyên Phong.","phamCap":"Không rõ","anchor":"Thạch Hạo thấy thế, cười lạnh một tiếng, lấy ra Đại La Tiên Kiếm, nhẹ nhàng vạch một cái"}]},"nguon":["@c1105","@c1212"]},{"id":"tran-ky-cua-nhom-nguoi-theo-duoi-luc-da","name":"Trận kỳ của nhóm người theo đuổi Lục Đà","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm trận pháp","phanLoaiPhu":"Trận kỳ","phamCap":"Không rõ","soHuu":["Năm người theo đuổi bày trận của Lục Đà"],"trangThai":"Bị phá hoại","blurb":"Những lá trận kỳ được nhóm người theo đuổi Lục Đà dùng để triển khai kỳ trận vây Thạch Hạo.","detail":"Năm người lấy trận kỳ ra nhằm hợp thành kỳ trận giam Thạch Hạo. Hắn áp sát trước khi trận pháp hoàn chỉnh và phá hoại các trận kỳ.","dacDiem":"Cần nhiều người phối hợp bố trí để hợp thành kỳ trận.","congNang":["Dùng làm trận cơ để triển khai kỳ trận giam giữ đối thủ."],"chuHienThoi":"Năm người theo đuổi bày trận của Lục Đà","chuSoHuu":[{"ten":"Năm người theo đuổi bày trận của Lục Đà","tuChuong":"@c1106","denChuong":"@c1106","cachCoDuoc":"Mang theo để triển khai kỳ trận do Lục Đà ban","trangThai":"Bị phá hoại"}],"capNhatToi":"@c1106","tabs":{"tienTrinh":[{"chuong":"@c1106","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị phá khi bày trận","phamCap":"Không rõ","text":"Các trận kỳ được lấy ra để vây Thạch Hạo nhưng bị hắn phá hoại trước khi kỳ trận hợp lại.","anchor":"Trận pháp không thể hợp lại, Thạch Hạo dường như một vị huyễn ma giống như, ngang dọc xung kích, phá hoại bọn họ trận kỳ."}]},"nguon":["@c1106"]},{"id":"than-dan-chua-thuong-cua-vuong-hi","name":"Thần đan chữa thương của Vương Hi","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"","soHuu":["Vương Hi"],"trangThai":"Đã sử dụng","blurb":"Viên thần đan được Vương Hi uống sau khi thoát khỏi cuộc vây đánh của Yêu Nguyệt và Huyền Côn.","detail":"Thần đan giúp Vương Hi bắt đầu chữa thương và khôi phục nguyên khí, nhưng không khiến nàng lập tức hồi phục hoàn toàn.","chuHienThoi":"Vương Hi","congNang":["Chữa thương và hỗ trợ khôi phục nguyên khí."],"chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1107","denChuong":"@c1107","cachCoDuoc":"","trangThai":"đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1107","loai":"dùng","importance":"normal","giaiDoan":"Chữa thương sau khi phá vây","text":"Vương Hi uống thần đan rồi ngồi điều tức để chữa thương và khôi phục nguyên khí.","anchor":"ăn thêm một viên tiếp theo thần đan"}]},"capNhatToi":"@c1107","nguon":["@c1107"]},{"id":"chien-xa-bay-mau-cua-vuong-hi","name":"Chiến xa bảy màu của Vương Hi","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến xa","phamCap":"Không rõ","soHuu":["Vương Hi"],"trangThai":"Đang được Vương Hi sở hữu","blurb":"Chiến xa bảy màu được Vương Hi dùng để rời khỏi vùng thú triều sau khi chịu đạo thương.","detail":"Dù không có thần thú kéo, chiến xa vẫn có thể được người điều khiển thôi thúc bay với tốc độ cao, đổi lại tiêu hao nhiều thần lực.","phanLoaiPhu":"Chiến xa ngự không","congNang":["Có thể ngự không với tốc độ cao khi không có thần thú kéo."],"chuHienThoi":"Vương Hi","chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1108","denChuong":"","cachCoDuoc":"Đã sở hữu trước khi được ghi nhận","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1108","tabs":{"tienTrinh":[{"chuong":"@c1108","loai":"dùng","importance":"normal","giaiDoan":"Rời vùng thú triều","text":"Vương Hi lấy chiến xa bảy màu ra, còn Thạch Hạo dùng thần lực thôi thúc nó đưa cả hai rời khỏi khu vực nguy hiểm.","anchor":"mặc dù vô thần thú lôi kéo, cũng có thể ngự không mà đi, tốc độ cực nhanh","phamCap":"Không rõ"}]},"nguon":["@c1108"]},{"id":"bi-bao-thu-liem-khi-tuc-cua-vuong-gia","name":"Bí bảo thu liễm khí tức của Vương gia","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"","soHuu":["Vương Hi"],"trangThai":"Đang do Vương Hi nắm giữ","blurb":"Bí bảo của Vương gia có khả năng che giấu toàn bộ khí tức của người sử dụng.","detail":"Vương Hi dùng bí bảo này khi đang trọng thương và tránh được sự dò tìm của Phong Hành Thiên, dù bóng tối của đối phương đã bao trùm vùng núi.","nguonGoc":"Vương gia","chuHienThoi":"Vương Hi","congNang":["Thu liễm toàn bộ khí tức của người sử dụng."],"dacDiem":"Khả năng ẩn giấu đủ để Phong Hành Thiên không tìm ra Vương Hi.","chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1109","denChuong":"","cachCoDuoc":"Bí bảo của gia tộc","trangThai":"đang sở hữu"}],"capNhatToi":"@c1109","tabs":{"tienTrinh":[{"chuong":"@c1109","loai":"dùng","importance":"normal","giaiDoan":"Ẩn giấu khí tức","text":"Vương Hi dùng bí bảo thu liễm toàn bộ khí tức và tránh được sự dò tìm của Phong Hành Thiên.","anchor":"có thể để cho tự thân thu lại hết thảy khí tức","phamCap":""}]},"nguon":["@c1109"]},{"id":"hoang-kim-chien-dao","name":"Hoàng kim chiến đao","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"đang được sử dụng","blurb":"Binh khí màu vàng được Thạch Hạo dùng để quét sạch lực lượng đi theo Phong Hành Thiên.","detail":"Chiến đao có thể phóng lớn và phát ra ánh đao quét ngang, liên tiếp chém giết người theo đuổi cùng một số đệ tử Thiên Thần Thư Viện.","phanLoaiPhu":"Chiến đao","hinhDang":"Chiến đao màu vàng có thể phóng lớn","uyLuc":"Ánh đao quét ngang đủ sức chém giết nhiều tu sĩ đã tu thành tiên khí.","dacDiem":"Có thể phóng lớn trong lúc được vận dụng.","chuHienThoi":"Thạch Hạo","congNang":["Phóng lớn thân đao và phát ánh đao quét ngang."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1110","denChuong":"","cachCoDuoc":"","trangThai":"đang sử dụng"}],"capNhatToi":"@c1110","tabs":{"tienTrinh":[{"chuong":"@c1110","loai":"dùng","importance":"normal","giaiDoan":"Quét sạch người theo đuổi","text":"Thạch Hạo phóng lớn hoàng kim chiến đao rồi quét ngang, chém giết lực lượng đi theo Phong Hành Thiên.","anchor":"trong tay hoàng kim chiến đao phóng to, lần thứ hai xoay tròn lên, quét ngang mà qua","phamCap":"Không rõ"}]},"nguon":["@c1110"]},{"id":"than-duoc-trong-cung-dien-duoi-long-dat","name":"Thần dược trong cung điện dưới lòng đất","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Dược vật","phamCap":"Thần dược","soHuu":[],"trangThai":"trốn vào cung điện dưới lòng đất","blurb":"Một cây thần dược ẩn tại vực sâu bên dưới chiến trường tiên gia.","detail":"Sau khi dư ba trận chiến làm lộ cung điện dưới lòng đất, cây thần dược hiện thân, tỏa mùi thơm rồi chui qua lớp đất để trốn vào bên trong.","phanLoaiPhu":"Linh dược","hinhDang":"Một cây thần dược","nguonGoc":"Khu vực cung điện dưới lòng đất","uyLuc":"Không rõ","dacDiem":"Có khả năng chui qua lớp đất để bỏ chạy.","chuHienThoi":"","congNang":["Độn qua lớp đất để trốn vào cung điện dưới lòng đất."],"chuSoHuu":[],"capNhatToi":"@c1110","tabs":{"tienTrinh":[{"chuong":"@c1110","loai":"xuất hiện","importance":"normal","giaiDoan":"Hiện thân trong vực sâu","text":"Cây thần dược hiện thân sau khi cung điện dưới lòng đất bị đánh lộ rồi chui vào lớp đất để chạy trốn.","anchor":"vực sâu bên trong quả nhiên có một cây thần dược xuất hiện, nó đâm vào trong lớp đất","phamCap":"Thần dược"}]},"nguon":["@c1110"]},{"id":"chien-mau-mau-den","name":"Chiến mâu màu đen","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Chưa xác định","soHuu":["Phong Hành Thiên"],"trangThai":"Đang được sử dụng","blurb":"Chiến mâu xuất hiện trong bóng tối khi Phong Hành Thiên săn giết các đối thủ.","detail":"Binh khí quét ngang Huyền Côn và suýt gây thương tích nghiêm trọng ở eo trước khi bị hắn dùng một chưởng đánh bật.","hinhDang":"Chiến mâu màu đen","congNang":["Tập kích mục tiêu trong bóng tối."],"chuHienThoi":"Phong Hành Thiên","chuSoHuu":[{"ten":"Phong Hành Thiên","tuChuong":"@c1112","denChuong":"","cachCoDuoc":"","trangThai":"đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1112","loai":"dùng","importance":"normal","giaiDoan":"Tập kích Huyền Côn","text":"Chiến mâu từ bóng tối quét ngang Huyền Côn và suýt rạch trúng eo hắn.","anchor":"một cái chiến mâu màu đen quét ra","phamCap":"Chưa xác định"}]},"capNhatToi":"@c1112","nguon":["@c1112"]},{"id":"chan-huyet-hoang-diep-toc","name":"Chân huyết Hoàng Điệp tộc","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chân huyết Trường Sinh giả","phamCap":"Không rõ","soHuu":["Hoàng Điệp"],"trangThai":"Tạm niêm phong trong cơ thể Hoàng Điệp","blurb":"Chân huyết màu vàng có nguồn gốc từ cổ điệp mục nát, được Hoàng Điệp tiếp nhận làm vật dẫn cho truyền thừa của Hoàng Điệp tộc. Sau khi đi vào cơ thể Hoàng Điệp, chân huyết được tạm thời niêm phong trong huyết nhục để chờ luyện hóa.","detail":"Chân huyết Hoàng Điệp tộc vốn thuộc về một cổ điệp mục nát. Tại @c1116, đoàn chân huyết màu vàng đi vào cơ thể Hoàng Điệp, đổi chủ và trở thành vật dẫn cho truyền thừa cùng tộc. Hoàng Điệp chưa dung hợp ngay mà tạm thời niêm phong chân huyết trong huyết nhục, chờ có thêm thời gian để luyện hóa.","phanLoaiPhu":"Chân huyết truyền thừa","nguonGoc":"Cổ điệp mục nát","dacDiem":"Có màu vàng, đi vào cơ thể Hoàng Điệp và được tạm thời niêm phong trong huyết nhục để chờ luyện hóa.","chuHienThoi":"Hoàng Điệp","congNang":["Làm vật dẫn cho truyền thừa của Hoàng Điệp tộc."],"chuSoHuu":[{"ten":"Hoàng Điệp","tuChuong":"@c1116","denChuong":"","cachCoDuoc":"Tiếp nhận từ di hài cổ điệp cùng tộc","trangThai":"Tạm niêm phong trong cơ thể"}],"tabs":{"tienTrinh":[{"chuong":"@c1116","loai":"đổi chủ","importance":"major","giaiDoan":"Truyền cho Hoàng Điệp","text":"Chân huyết màu vàng từ cổ điệp đi vào cơ thể Hoàng Điệp và được tạm thời niêm phong để chờ luyện hóa.","anchor":"đặc biệt là một đoàn màu vàng chân huyết càng là đi vào trong cơ thể nó","phamCap":"Không rõ"}]},"capNhatToi":"@c1116","nguon":["@c1116"]},{"id":"hoa-diep-lan","name":"Hỏa diệp lan","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Thần dược","phamCap":"Thần dược","soHuu":[],"trangThai":"Chưa bị bắt","blurb":"Thần dược đỏ như lửa có thể hòa vào lòng đất để né tránh người truy bắt.","detail":"Hỏa diệp lan liên tục xuất hiện rồi chui vào đất khi Yêu Nguyệt và Huyền Côn truy bắt. Thạch Hạo nghi hành động của nó nhằm giữ ba người ở lại cho đến khi sinh linh không đầu trở về.","phanLoaiPhu":"Linh dược có khả năng độn thổ","hinhDang":"Toàn thân đỏ đậm như ngọn lửa đang cháy","dacDiem":"Tỏa tinh khí và có thể hòa vào lớp đất để đào thoát.","congNang":["Hòa vào lòng đất để né tránh việc bắt giữ."],"tabs":{"tienTrinh":[{"chuong":"@c1116","loai":"xuất hiện","importance":"normal","giaiDoan":"Né tránh truy bắt","text":"Hỏa diệp lan xuất hiện trong trung ương cung điện và liên tục hòa vào đất để tránh Yêu Nguyệt cùng Huyền Côn.","anchor":"Đó là một cây hỏa diệp lan, toàn thân đỏ đậm, như hỏa diễm đang thiêu đốt","phamCap":"Thần dược"}]},"capNhatToi":"@c1116","nguon":["@c1116"]},{"id":"cot-thuoc-trang-nhu-ngoc","name":"Cốt thược trắng như ngọc","cn":"","aliases":["Bạch cốt chìa khóa"],"category":"khac","categoryLabel":"Chìa khóa bằng xương","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Được phát hiện trong tế đàn","blurb":"Chìa khóa bằng mảnh xương trắng được giấu trong kết cấu của tế đàn trung tâm.","detail":"Chìa khóa có hình dáng tương ứng với rãnh dài trong bảo hộp trên tế đàn. Võ đạo Thiên nhãn không phát hiện được nó; Thạch Hạo chỉ nhìn thấy chìa khóa qua khe nứt sau khi dốc sức dịch chuyển tế đàn.","phanLoaiPhu":"Chìa khóa","hinhDang":"Chìa khóa dài được mài từ mảnh xương trắng loáng","vatLieu":"Mảnh xương trắng","nguonGoc":"Ẩn trong tế đàn trung tâm","dacDiem":"Không bị Võ đạo Thiên nhãn phát hiện khi còn giấu trong tế đàn.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1116","denChuong":"","cachCoDuoc":"Phát hiện qua khe nứt sau khi dịch chuyển tế đàn","trangThai":"Đã phát hiện"}],"tabs":{"tienTrinh":[{"chuong":"@c1116","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ ra trong tế đàn","text":"Thạch Hạo dịch chuyển tế đàn nứt vỡ và phát hiện chìa khóa bằng bạch cốt được giấu trong kết cấu bên trong.","anchor":"phát hiện trong tế đàn có một viên bạch cốt chìa khoá, lấy trắng loáng mảnh xương đánh bóng mà thành","phamCap":"Không rõ"}]},"capNhatToi":"@c1116","nguon":["@c1116"]},{"id":"te-dan-tim-nhat","name":"Tế đàn tím nhạt","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn đá","phamCap":"Không rõ","soHuu":[],"trangThai":"Đã bị phá giải thể","blurb":"Tế đàn đá tím nhạt, dày nặng và mang quý khí trong cung điện dưới lòng đất.","detail":"Cốt thược trắng như ngọc được giấu trong một khe nứt của tế đàn. Thạch Hạo phá tung tế đàn để tìm kiếm nhưng không phát hiện thêm vật gì.","hinhDang":"Tế đàn bằng đá màu tím nhạt.","vatLieu":"Đá dày nặng","dacDiem":"Mang một loại quý khí và có khe nứt giấu cốt thược.","tabs":{"tienTrinh":[{"chuong":"@c1117","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Tìm kiếm cốt thược","text":"Thạch Hạo phá tế đàn tím nhạt thành nhiều phần để kiểm tra sau khi lấy được cốt thược.","anchor":"Tế đàn rất bất phàm, hiện màu tím nhạt, thạch thể dày nặng, có một loại quý khí","phamCap":"Không rõ"}]},"capNhatToi":"@c1117","nguon":["@c1117"]},{"id":"hon-dang-cua-phong-hanh-thien","name":"Hồn đăng của Phong Hành Thiên","cn":"","aliases":[],"category":"khac","categoryLabel":"Hồn đăng","phamCap":"Không rõ","soHuu":["Phong Hành Thiên"],"trangThai":"Đã tắt","blurb":"Hồn đăng của Phong Hành Thiên được đặt trên chiến thuyền hoàng kim, dùng để phản ánh trạng thái sinh tử của hắn. Khi ngọn đèn tắt, cái chết của Phong Hành Thiên được xác nhận.","detail":"Hồn đăng được đặt trên chiến thuyền hoàng kim và gắn với trạng thái sinh tử của Phong Hành Thiên. Việc hồn đăng tắt sau khi hắn tử vong đã trở thành bằng chứng xác nhận cái chết này, gây chấn động cho những người trong Tiên gia chiến trường. @c1117","congNang":["Báo trạng thái sinh tử của Phong Hành Thiên; khi hồn đăng tắt, có thể xác nhận hắn đã chết. @c1117"],"dacDiem":"Được đặt trên chiến thuyền hoàng kim; đã tắt sau khi Phong Hành Thiên tử vong.","tabs":{"tienTrinh":[{"chuong":"@c1117","loai":"nhắc tới","importance":"major","giaiDoan":"Xác nhận cái chết","text":"Hồn đăng trên chiến thuyền hoàng kim tắt, xác nhận Phong Hành Thiên đã chết.","anchor":"Chiến thuyền hoàng kim trên hồn đăng tắt, ngươi nói là thật hay giả","phamCap":"Không rõ"}]},"capNhatToi":"@c1117","nguon":["@c1117"]},{"id":"co-chien-xa-cua-vuong-hi","name":"Cổ chiến xa của Vương Hi","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến xa","phamCap":"Không rõ","soHuu":["Vương Hi"],"trangThai":"Bị hư hại","blurb":"Cổ chiến xa do Vương Hi sử dụng, bị tổn hại sau một cuộc truy sát kéo dài.","detail":"Khi Vương Hi gặp lại Thạch Hạo, cổ chiến xa đã bị hao tổn như vừa phải chịu một đòn nghiêm trọng.","chuHienThoi":"Vương Hi","chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1117","denChuong":"","cachCoDuoc":"Không nêu trong chương này","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1117","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Sau cuộc truy sát","text":"Cổ chiến xa của Vương Hi bị hư hại nghiêm trọng sau khi nàng thoát khỏi cuộc truy sát.","anchor":"chiếc kia cổ chiến xa đều bị hao tổn, như là từng tao ngộ đòn nghiêm trọng","phamCap":"Không rõ"}]},"capNhatToi":"@c1117","nguon":["@c1117"]},{"id":"can-khon-dai","name":"Càn Khôn đại","cn":"","aliases":["Càn Khôn Đại","Túi Càn Khôn"],"category":"phap-bao","categoryLabel":"Vô thượng chí bảo","phamCap":"Có thể là pháp khí Tiên Vương","soHuu":["Thế giới bên kia Biên Hoang"],"trangThai":"nguyên vẹn","blurb":"Càn Khôn đại là chí bảo nguyên thủy từng thất lạc sang phía bên kia Biên Hoang và đã bị thế giới bên kia luyện hóa. Pháp bảo có thể thu nhận vạn vật, mở không gian riêng, phóng sát phong và đối kháng quy tắc thiên địa để che chở, hỗ trợ sinh linh dị giới vượt giới. (+) Tiên khí hoàn hảo từng thuộc Cửu Thiên nhưng đã thất lạc sang dị vực. Mười hai lão giả dị vực mang nó ra đối đầu nhóm Mạnh Thiên Chính. [CAN-SOAT-GOP]","detail":"Càn Khôn đại được truyền là luyện bằng hỗn độn từ hơn vạn tấm da thần thú, có thể là pháp khí của Tiên Vương. Sau khi thất lạc sang phía bên kia Biên Hoang và rơi vào tay địch, nó tái hiện trong trạng thái đã bị thế giới bên kia luyện hóa, vượt qua đường nối giữa hỗn độn khí và ngũ sắc thần hà nhưng lập tức bị quy tắc thiên địa đồng loạt áp chế (@c1118–@c1119). Pháp bảo từng mở một vùng không gian bao phủ ngọn núi đen; về sau còn phồng lớn che kín bầu trời, đối kháng pháp tắc cùng trật tự thế giới và giao kích thăm dò với Thập Giới (@c1139).","phanLoaiPhu":"Túi chí bảo","hinhDang":"Một chiếc túi tỏa hỗn độn khí và ngũ sắc thần hà","vatLieu":"Hơn vạn tấm da thần thú dung hợp","nguonGoc":"Được truyền là luyện từ hơn vạn tấm da thần thú bằng hỗn độn và từng thất lạc phía bên kia Biên Hoang.","uyLuc":"Luồng gió phóng ra từ trong túi có thể diệt Thiên Thần, thậm chí giết giáo chủ.","dacDiem":"Tỏa hỗn độn khí và ngũ sắc thần hà; có thể là pháp khí của Tiên Vương, nhưng chịu sự áp chế của quy tắc thiên địa hiện tại.","chuHienThoi":"Không rõ","congNang":["Phóng ra luồng gió có thể diệt Thiên Thần, thậm chí giết giáo chủ.","Thu nhận vạn vật.","Mở một vùng không gian riêng bao phủ ngọn núi đen (@c1119).","Đối kháng quy tắc thiên địa để hỗ trợ sinh linh dị giới vượt giới.","Đối kháng pháp tắc và trật tự thế giới; có thể phồng lên che phủ bầu trời (@c1139).","Che chở khu vực của sinh linh dị vực trước sự trừng phạt của quy tắc."],"tabs":{"tienTrinh":[{"chuong":"@c1118","loai":"xuất hiện","importance":"major","giaiDoan":"Vượt qua đường nối","text":"Càn Khôn đại vượt qua đường nối, tỏa hỗn độn khí và ngũ sắc thần hà rồi bị quy tắc thiên địa đồng loạt áp chế.","anchor":"lối đi kia bên trong lao ra một cái túi áo, phát sinh hỗn độn khí, lưu động ngũ sắc thần hà","phamCap":"Có thể là pháp khí Tiên Vương"},{"chuong":"@c1119","loai":"đổi chủ","importance":"major","giaiDoan":"Bị luyện hóa và dùng để phá giới","phamCap":"Binh khí Tiên Vương","text":"Càn Khôn đại tái hiện trong trạng thái đã bị thế giới bên kia luyện hóa, mở không gian bao phủ ngọn núi đen và đối kháng quy tắc Cửu Thiên Thập Địa để tạo đường vượt giới.","anchor":"nó đang đối kháng với mảnh này đại thiên địa"},{"chuong":"@c1139","loai":"dùng","importance":"normal","giaiDoan":"Đối đầu Thập Giới Đồ","text":"Càn Khôn Đại phồng lên che phủ bầu trời để đối kháng quy tắc và trật tự, sau đó giao kích thăm dò với Thập Giới Đồ.","anchor":"Càn Khôn Đại gồ lên lên, chặn lại bầu trời, đối kháng quy tắc cùng trật tự","phamCap":"Chí bảo"}]},"capNhatToi":"@c1118","nguon":["@c1118","@c1119","@c1139","@c1374"],"chuSoHuu":[{"ten":"Thế giới bên kia Biên Hoang","tuChuong":"@c1119","denChuong":"","cachCoDuoc":"Chí bảo thất lạc tại phía bên kia Biên Hoang và bị luyện hóa.","trangThai":"Đang nắm giữ"}]},{"id":"bo-xuong-my-nu-cua-co-toc-truong-sinh","name":"Bộ xương mỹ nữ của cổ tộc Trường Sinh","cn":"","aliases":[],"category":"khac","categoryLabel":"Hài cốt","phamCap":"Hài cốt của cường giả ít nhất vượt Giáo Chủ cấp","soHuu":["Sinh linh mượn bộ xương mỹ nữ"],"trangThai":"Đang bị chiếm dụng","blurb":"Hài cốt trắng như ngọc của một nữ tổ tiên thuộc cổ tộc Trường Sinh. Sinh linh thế giới bên kia dùng bộ xương làm vật dẫn để vượt qua đường nối.","detail":"Chủ nhân bộ xương khi còn sống là một mỹ nhân tuyệt đại và có tu vi được đánh giá ít nhất vượt Giáo Chủ cấp. Một trưởng lão Thiên Thần Thư Viện nhận ra đây là tổ tiên trong tộc mình.","phanLoaiPhu":"Hài cốt nữ cường giả","hinhDang":"Bộ xương trắng như ngọc mang hình người nữ giới","nguonGoc":"Di cốt của nữ tổ tiên thuộc một cổ tộc Trường Sinh","dacDiem":"Không còn huyết nhục nhưng vẫn có thể được dùng làm vật dẫn vượt giới.","chuHienThoi":"Sinh linh mượn bộ xương mỹ nữ","capNhatToi":"@c1119","congNang":["Làm vật dẫn để sinh linh thế giới bên kia vượt qua đường nối giữa hai giới."],"chuSoHuu":[{"ten":"Sinh linh mượn bộ xương mỹ nữ","tuChuong":"@c1119","denChuong":"","cachCoDuoc":"Mượn di cốt đang nằm trong tay thế giới bên kia.","trangThai":"Đang chiếm dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1119","loai":"dùng","importance":"normal","giaiDoan":"Bị dùng làm vật dẫn vượt giới","phamCap":"Hài cốt của cường giả ít nhất vượt Giáo Chủ cấp","text":"Sinh linh dị giới mượn bộ xương của nữ tổ tiên cổ tộc Trường Sinh để vượt qua đường nối và xuất hiện trên ngọn núi đen.","anchor":"đây chỉ là một bộ khung xương, không hề có một chút huyết nhục"}]},"nguon":["@c1119"]},{"id":"thap-gioi-do","name":"Thập Giới Đồ","cn":"","aliases":["Mười giới đồ"],"category":"phap-bao","categoryLabel":"Hỗn Độn chí bảo","phamCap":"Hỗn Độn chí bảo","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Được dùng trấn áp dấu ấn","blurb":"Chí bảo chứa sơn hà và đại tinh chân thực, từng lập uy danh trong trận chiến cuối thời Tiên cổ. (+) Hỗn Độn chí bảo có thể mở ra không gian và tiếp dẫn người tiến vào. [CAN-SOAT-GOP] (+) Bảo vật quan trọng được lệnh mang tới Biên Hoang cùng Tổ Long kèn lệnh để ứng cứu chiến trường. [CAN-SOAT-GOP]","detail":"Thập Giới Đồ phát ra thần mang để mở lối cho đoàn kỳ tài. Khi phối hợp với Càn Khôn đại, bảo vật góp phần hình thành một vùng thiên địa rộng lớn, tràn đầy sinh cơ và được ngăn cách bằng giới bích hỗn độn.","phanLoaiPhu":"Đồ quyển","congNang":["Phát thần mang mở lối và tiếp dẫn người vào không gian bên trong.","Phối hợp với Càn Khôn đại để hình thành một vùng thiên địa gần với cổ giới.","Trấn áp dấu ấn Bất Hủ giả đang phát tác trong Nguyên Thần Mạc Đạo tại @c1149."],"dacDiem":"Khi kết hợp với Càn Khôn đại, không gian do bảo vật tạo thành có sinh mệnh và giới bích hỗn độn.","chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1120","loai":"dùng","importance":"normal","giaiDoan":"Mở không gian chiến trường","text":"Thập Giới Đồ phát thần mang mở lối và phối hợp với Càn Khôn đại để tạo thành một vùng thiên địa rộng lớn.","anchor":"Thập Giới Đồ từng lấp lóe thần mang, rọi sáng ra một mảnh","phamCap":"Hỗn Độn chí bảo"},{"chuong":"@c1149","loai":"dùng","importance":"normal","giaiDoan":"Trấn áp dấu ấn","text":"Thập Giới Đồ được lấy ra cùng Cửu Hoàng lô để trấn áp dấu ấn Bất Hủ giả trong đầu Mạc Đạo.","anchor":"bọn họ lấy ra Thập Giới Đồ, Cửu Hoàng lô, nhanh chóng trấn áp đến tất cả","phamCap":"Trọng khí"}]},"capNhatToi":"@c1120","nguon":["@c1120","@c1149","@c1299","@c1332"]},{"id":"dao-phu-bao-menh-cua-hu-khong-thu","name":"Đạo phù bảo mệnh của Hư Không Thú","cn":"","category":"phap-bao","categoryLabel":"Thần phù","phamCap":"Không rõ","soHuu":["Hư Không Vương Thú"],"trangThai":"Đã vỡ thành tro","blurb":"Đạo phù bảo mệnh được một siêu cấp đại nhân vật đặt trong nguyên thần Hư Không Vương Thú nhằm ngăn nó chết tại thế giới này. Khi chủ thể lâm vào sát cảnh, đạo phù phát động lực lượng hư không để cứu mạng và tái sinh hoàn toàn thân thể, sau đó vỡ thành tro.","detail":"Đạo phù vốn ẩn trong nguyên thần Hư Không Vương Thú và chứa lực lượng hư không. Khi Hư Không Vương Thú sắp bị giết, nó lao ra khỏi nguyên thần, đẩy văng Thạch Hạo, đưa chủ thể vượt qua hư không và tái sinh toàn bộ thân thể, bao gồm cả những chiếc sừng đã gãy. Sau khi hoàn thành công năng bảo mệnh, đạo phù vỡ thành tro. @c1125","phanLoaiPhu":"Bảo mệnh phù","nguonGoc":"Được một siêu cấp đại nhân vật đặt trong nguyên thần Hư Không Vương Thú.","uyLuc":"Có thể cứu Hư Không Vương Thú khỏi sát cảnh và tái sinh hoàn toàn thân thể cùng những chiếc sừng đã gãy. @c1125","dacDiem":"Ẩn trong nguyên thần Hư Không Vương Thú, chứa lực lượng hư không và vỡ thành tro sau một lần hoàn thành công năng bảo mệnh.","chuHienThoi":"Hư Không Vương Thú","congNang":["Đẩy văng kẻ đang công kích và đưa Hư Không Vương Thú vượt qua hư không để thoát khỏi sát cảnh. @c1125","Tái sinh hoàn toàn thân thể Hư Không Vương Thú, kể cả những chiếc sừng đã gãy. @c1125"],"chuSoHuu":[{"ten":"Hư Không Vương Thú","tuChuong":"@c1125","denChuong":"@c1125","cachCoDuoc":"Được một siêu cấp đại nhân vật lưu trong nguyên thần.","trangThai":"đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c1125","loai":"dùng","importance":"major","giaiDoan":"Kích hoạt bảo mệnh","text":"Đạo phù lao ra khỏi nguyên thần, cứu Hư Không Vương Thú khỏi cái chết, tái sinh hoàn toàn thân thể rồi vỡ thành tro.","anchor":"mi tâm của nó bên trong, nguyên thần bên trong có một khối cổ xưa đạo phù lao ra","phamCap":"Không rõ"}]},"capNhatToi":"@c1125","nguon":["@c1125"]},{"id":"phuong-hoang-chan-huyet","name":"Phượng Hoàng chân huyết","cn":"","category":"nguyen-lieu","categoryLabel":"Bảo huyết","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã dùng","blurb":"Một giọt Phượng Hoàng chân huyết được Thạch Hạo phong ấn trong thủy tinh để dùng khi nguy cấp.","detail":"Thạch Hạo nuốt giọt chân huyết trước khi tái chiến với Hư Không Vương Thú. Huyết dịch khiến bảo quang bùng lên, tinh khí cuồn cuộn và giúp hắn phục hồi trong chớp mắt như Phượng Hoàng niết bàn.","phanLoaiPhu":"Chân huyết","hinhDang":"Một giọt huyết dịch được phong ấn trong thủy tinh.","uyLuc":"Giúp Thạch Hạo nhanh chóng phục hồi nguyên khí trước khi tái chiến.","dacDiem":"Khi sử dụng tạo ra bảo quang vô lượng và trạng thái giống Phượng Hoàng niết bàn.","chuHienThoi":"Thạch Hạo","congNang":["Nhanh chóng khôi phục tinh khí và nguyên khí của người sử dụng tại @c1125."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1125","denChuong":"@c1125","cachCoDuoc":"Được dự trữ trong một viên thủy tinh.","trangThai":"đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c1125","loai":"dùng","importance":"normal","giaiDoan":"Phục hồi giữa trận","text":"Thạch Hạo lấy giọt Phượng Hoàng chân huyết được phong ấn trong thủy tinh ra dùng để phục hồi nguyên khí.","anchor":"Thạch Hạo không nói hai lời, lấy ra một viên thủy tinh, ở trong phong ấn một giọt Phượng Hoàng chân huyết","phamCap":"Không rõ"}]},"capNhatToi":"@c1125","nguon":["@c1125"]},{"id":"dai-dinh-chua-than-tuyen","name":"Đại đỉnh chứa thần tuyền","cn":"","aliases":[],"category":"khac","categoryLabel":"Dụng cụ","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được Thạch Hạo giữ","blurb":"Một chiếc đại đỉnh được Thạch Hạo đổ đầy thần tuyền để chứa và chuẩn bị nấu thịt Hư Không Vương Thú.","detail":"Thạch Hạo đặt tảng thịt dài khoảng mười trượng của Hư Không Vương Thú vào đỉnh. Sau khi giết đối phương, hắn thu lại đại đỉnh cùng phần thịt còn sót và mang về chiến trường.","phanLoaiPhu":"Đỉnh chứa thực phẩm","dacDiem":"Bên trong được đổ đầy thần tuyền.","chuHienThoi":"Thạch Hạo","capNhatToi":"@c1126","congNang":["Chứa thần tuyền và phần thịt Hư Không Vương Thú để chuẩn bị nấu."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1126","denChuong":"","cachCoDuoc":"Tự lấy ra khi thẩm vấn Hư Không Vương Thú","trangThai":"dang-giu"}],"tabs":{"tienTrinh":[{"chuong":"@c1126","loai":"dùng","importance":"normal","giaiDoan":"Chứa thịt Hư Không Thú","text":"Thạch Hạo đổ thần tuyền vào đại đỉnh rồi đặt phần thịt đã chặt từ Hư Không Vương Thú vào trong. Hắn thu lại chiếc đỉnh và mang nó trở về chiến trường.","anchor":"Thạch Hạo nói, lấy ra một cái đại đỉnh, ở trong truyền vào đầy thần tuyền, chuẩn bị đưa nó cho luộc","phamCap":"Chưa rõ"}]},"nguon":["@c1126"]},{"id":"bao-ham-hon-thap","name":"Bao Hàm Hồn tháp","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Ma khí","phanLoaiPhu":"Ma khí Tiên cổ","phamCap":"Ma khí hiếm thấy","soHuu":["Mạc Đạo","Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Đang được Thạch Hạo nắm giữ","hinhDang":"Tòa tiểu tháp bằng bạch ngọc","nguonGoc":"Kỷ nguyên Tiên cổ","blurb":"Bao Hàm Hồn tháp là một tòa tháp bạch ngọc có từ kỷ nguyên Tiên cổ, vừa dưỡng hồn, làm lớn mạnh nguyên thần, vừa lưu giữ dấu ấn nguyên thần. Mạc Đạo lấy tháp từ mi tâm, chủ động giao cho Thạch Hạo cùng một phần dấu ấn nguyên thần của bản thân, qua đó trao cho Thạch Hạo phương tiện khống chế mình.","detail":"Bao Hàm Hồn tháp có nguồn gốc từ kỷ nguyên Tiên cổ và mang hình dáng một tòa tháp bạch ngọc. Pháp bảo này vốn nằm trong mi tâm Mạc Đạo; về sau, Mạc Đạo lấy nó ra và giao cho Thạch Hạo cùng bộ phận dấu ấn nguyên thần của mình. Nhờ dấu ấn được lưu giữ trong tháp, Thạch Hạo có thể khống chế Mạc Đạo. @c1132","uyLuc":"Có thể gánh chịu bộ phận dấu ấn nguyên thần, qua đó hỗ trợ khống chế người mang dấu ấn ấy.","dacDiem":"Tòa tháp bạch ngọc có từ kỷ nguyên Tiên cổ, kết hợp tác dụng dưỡng hồn với khả năng lưu giữ dấu ấn nguyên thần.","congNang":["Dưỡng hồn.","Làm lớn mạnh nguyên thần.","Gánh chịu và lưu giữ bộ phận dấu ấn nguyên thần.","Hỗ trợ khống chế người có dấu ấn nguyên thần được lưu trong tháp. @c1132"],"chuSoHuu":[{"ten":"Mạc Đạo","tuChuong":"@c1132","denChuong":"@c1132","cachCoDuoc":"Nắm giữ từ trước khi giao chiến với Thạch Hạo","trangThai":"Đã giao lại"},{"ten":"Thạch Hạo","tuChuong":"@c1132","denChuong":"","cachCoDuoc":"Được Mạc Đạo chủ động giao cùng một phần dấu ấn nguyên thần","trangThai":"Đang nắm giữ"}],"capNhatToi":"@c1132","dinhDanh":"goc","tabs":{"tienTrinh":[{"chuong":"@c1132","loai":"đổi chủ","importance":"major","giaiDoan":"Mạc Đạo giao cho Thạch Hạo","phamCap":"Ma khí hiếm thấy từ kỷ nguyên Tiên cổ","text":"Mạc Đạo lấy Bao Hàm Hồn tháp từ mi tâm và giao cho Thạch Hạo cùng bộ phận dấu ấn nguyên thần của mình. Vương Hi kiểm tra và xác nhận bí bảo không có vấn đề.","anchor":"Bao hàm hồn tháp, có thể dưỡng hồn, lớn mạnh Nguyên Thần, cũng có thể gánh chịu một người bộ phận Nguyên Thần dấu ấn, khống chế một người."}]},"nguon":["@c1132"]},{"id":"bao-menh-phu-cua-thien-than-thu-vien","name":"Bảo mệnh phù của Thiên Thần Thư Viện","cn":"","category":"khac","categoryLabel":"Phù lục","phamCap":"","soHuu":["Học viên Thiên Thần Thư Viện"],"trangThai":"đã kích hoạt trong chiến trường","blurb":"Phù lục bảo mệnh do trưởng lão Thiên Thần Thư Viện cấp cho học viên trước trận chiến.","detail":"Khi người mang phù bị giết trong hỗn chiến, phù nổi lên và cuốn họ rời khỏi chiến trường. Hiệu lực không tuyệt đối vì vẫn có tu sĩ tử vong hoàn toàn.","phanLoaiPhu":"Phù lục bảo mệnh","chuHienThoi":"Học viên Thiên Thần Thư Viện","congNang":["Cuốn người mang phù rời khỏi chiến trường khi họ bị giết trong hỗn chiến."],"dacDiem":"Không bảo đảm cứu được người mang trong mọi trường hợp.","capNhatToi":"@c1134","tabs":{"tienTrinh":[{"chuong":"@c1134","loai":"dùng","importance":"normal","giaiDoan":"Kích hoạt trong hỗn chiến","text":"Nhiều bảo mệnh phù nổi lên và cuốn những người vừa bị giết rời khỏi chiến trường, dù vẫn có trường hợp tử vong hoàn toàn.","anchor":"những kia bảo mệnh phù nổi lên sở hữu, quấn theo những kia chết đi người biến mất rồi"}]},"nguon":["@c1134"]},{"id":"co-phu-cua-chi-ton-tre-tuoi-di-vuc","name":"Cổ phù của chí tôn trẻ tuổi dị vực","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Phù lục","phamCap":"","soHuu":["Chí tôn trẻ tuổi dị vực đối đầu Mạc Đạo"],"trangThai":"Đã sử dụng","blurb":"Một đạo cổ phù được chí tôn trẻ tuổi dị vực thúc giục để tăng tốc đào thoát.","detail":"Cổ phù được sử dụng cùng Tử la đại pháp, giúp người sở hữu đạt tốc độ khiến hư không vặn vẹo và xuất hiện mảnh vỡ thời gian.","congNang":["Phối hợp với bí thuật thiêu đốt bản nguyên để tăng mạnh tốc độ thoát thân."],"chuHienThoi":"Chí tôn trẻ tuổi dị vực đối đầu Mạc Đạo","chuSoHuu":[{"ten":"Chí tôn trẻ tuổi dị vực đối đầu Mạc Đạo","tuChuong":"@c1137","denChuong":"","cachCoDuoc":"","trangThai":"đã sử dụng"}],"capNhatToi":"@c1137","nguon":["@c1137"]},{"id":"co-tran-dai","name":"Cổ trận đài","cn":"","aliases":[],"category":"khac","categoryLabel":"Trận đài truyền tống","phamCap":"","soHuu":[],"trangThai":"Còn hoạt động","blurb":"Một trận đài truyền tống cổ nằm trên chiến trường.","detail":"Chí tôn trẻ tuổi dị vực nhảy lên trận đài trong lúc tháo chạy và được Càn Khôn đại trận đưa ra khỏi chiến trường.","congNang":["Đưa người đứng trên trận đài rời khỏi chiến trường thông qua Càn Khôn đại trận."],"capNhatToi":"@c1137","nguon":["@c1137"]},{"id":"chan-nhen-tam-dau-vuong","name":"Chân nhện Tam Đầu Vương","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Chiến lợi phẩm","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Còn nguyên","blurb":"Chiếc chân nhện khổng lồ duy nhất còn lại sau khi Tam Đầu Vương bị đánh nổ.","detail":"Chiếc chân dài khoảng hai ba mươi trượng. Thạch Hạo vác nó trở lại chiến trường chính, khiến sinh linh của cả hai phe sửng sốt.","hinhDang":"Một chân nhện khổng lồ dài khoảng hai ba mươi trượng.","nguonGoc":"Tàn tích thân thể của Tam Đầu Vương sau khi bị Thạch Hạo đánh giết.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1137","denChuong":"","cachCoDuoc":"Thu được sau khi đánh giết Tam Đầu Vương.","trangThai":"đang có"}],"capNhatToi":"@c1137","nguon":["@c1137"]},{"id":"doan-hoa-hoa-guong","name":"Đoàn hỏa hóa gương","cn":"","aliases":[],"category":"khac","categoryLabel":"Dị hỏa","phanLoaiPhu":"Dị hỏa chưa rõ lai lịch","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Ẩn trong thân thể Thạch Hạo","blurb":"Đoàn hỏa bí ẩn có thể tự rời khỏi thân thể Thạch Hạo và hóa thành một chiếc gương. Nó soi chiếu dấu tích chiến đấu trong cổ cung thần kim rồi ghi lại khí thế đại đạo còn lưu lại.","detail":"Tại cổ địa hoang phế, đoàn hỏa bay khỏi thân thể Thạch Hạo và treo trên đầu hắn dưới hình dạng một chiếc gương. Ánh gương chiếu vào lỗ tên, quyền ấn cùng những dấu tích công kích trên cung điện để khắc lại đạo vận cổ xưa.","hinhDang":"Hóa thành một chiếc gương khi hoạt động","dacDiem":"Ẩn trong thân thể Thạch Hạo và đã bắt đầu có thể được hắn cảm ứng.","uyLuc":"Có khả năng ghi lại khí thế đại đạo còn lưu trong dấu tích chiến đấu cổ xưa.","congNang":["Soi chiếu các lỗ tên, quyền ấn và dấu tích chiến đấu trên cổ cung thần kim.","Khắc lại khí thế đại đạo còn lưu trong di tích."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1140","denChuong":"","cachCoDuoc":"Đã ẩn trong cơ thể trước khi tới cổ địa","trangThai":"Hiện còn trong thân thể"}],"tabs":{"tienTrinh":[{"chuong":"@c1140","loai":"dùng","importance":"normal","giaiDoan":"Hóa gương ghi đạo vận","text":"Đoàn hỏa rời khỏi thân thể Thạch Hạo, hóa thành gương để soi các dấu tích chiến đấu và khắc lại khí thế đại đạo trong cổ cung.","anchor":"hóa thành một chiếc gương, soi sáng những kia tiễn khổng, quyền ấn, khắc lại các loại đại đạo khí thế","phamCap":"Không rõ"}]},"capNhatToi":"@c1140","nguon":["@c1140"]},{"id":"tien-nhuong","name":"Tiên nhưỡng","cn":"","aliases":["Tiên tửu trong bầu rượu"],"category":"khac","categoryLabel":"Rượu tiên","phanLoaiPhu":"Tiên tửu","phamCap":"Không rõ","soHuu":["Nữ tử là dấu ấn tan nát"],"chuHienThoi":"Nữ tử là dấu ấn tan nát","trangThai":"Được rót mời Thạch Hạo","blurb":"Loại rượu óng ánh trong suốt được nữ tử trong kim loại cổ cung dùng để tiếp đãi Thạch Hạo. Rượu tỏa tiên khí và hương thơm mạnh, trong khi miệng vật chứa còn tràn ra hỗn độn khí.","detail":"Nữ tử rót tiên nhưỡng trong lúc bày thức ăn và tuyên bố sẽ trao cơ duyên cho Thạch Hạo. Chất rượu trong suốt, phát tán tiên khí và có biểu hiện khác thường tại miệng vật chứa.","dacDiem":"Chất lỏng óng ánh trong suốt, tỏa tiên khí và đi kèm hỗn độn khí tại miệng vật chứa.","congNang":["Được dùng làm rượu tiếp đãi Thạch Hạo trong kim loại cổ cung."],"chuSoHuu":[{"ten":"Nữ tử là dấu ấn tan nát","tuChuong":"@c1140","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang dùng để tiếp đãi Thạch Hạo"}],"tabs":{"tienTrinh":[{"chuong":"@c1140","loai":"xuất hiện","importance":"normal","giaiDoan":"Rót mời Thạch Hạo","text":"Nữ tử rót tiên nhưỡng óng ánh và tỏa tiên khí để tiếp đãi Thạch Hạo trong cổ cung.","anchor":"miệng ấm bên trong chảy ra chất lỏng óng ánh trong suốt, lại đang phát tán ra tiên khí","phamCap":"Không rõ"}]},"capNhatToi":"@c1140","nguon":["@c1140"]},{"id":"bau-ruou-da","name":"Bầu rượu đá","cn":"","aliases":["Thạch bầu rượu chứa tiên nhưỡng"],"category":"khac","categoryLabel":"Vật chứa tiên nhưỡng","phamCap":"Không rõ","soHuu":["Nữ tử là dấu ấn tan nát"],"trangThai":"Đặt trên bàn đá","blurb":"Bầu rượu bằng đá chứa tiên nhưỡng và gắn với một thử thách dành cho Thạch Hạo.","detail":"Nữ tử cho Thạch Hạo thử lay động và cầm bầu rượu. Nếu hắn thành công, một chuyện lớn bằng trời với ảnh hưởng cực kỳ sâu xa sẽ phát sinh.","phanLoaiPhu":"Bầu rượu","hinhDang":"Bầu rượu bằng đá","dacDiem":"Khả năng được cầm lên có liên hệ trực tiếp với một biến cố lớn chưa được tiết lộ.","chuHienThoi":"Nữ tử là dấu ấn tan nát","chuSoHuu":[{"ten":"Nữ tử là dấu ấn tan nát","tuChuong":"@c1141","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"đang giữ"}],"capNhatToi":"@c1141","tabs":{"tienTrinh":[{"chuong":"@c1141","loai":"xuất hiện","importance":"normal","giaiDoan":"Thử thách lay động bầu","text":"Thạch Hạo được phép thử lay động bầu rượu đá, một hành động có thể dẫn tới biến cố ảnh hưởng sâu xa.","anchor":"Nếu như ngươi có thể chấp này ấm, thì sẽ có chuyện lớn bằng trời phát sinh","phamCap":"Không rõ"}]},"dinhDanh":"goc","nguon":["@c1141"]},{"id":"mat-na-dong-xanh-cua-nu-tu-ao-trang","name":"Mặt nạ đồng xanh của nữ tử áo trắng","cn":"","aliases":["Mặt nạ bằng đồng xanh","Đại đạo bảo bình"],"category":"phap-bao","categoryLabel":"Chí bảo biến hóa","phanLoaiPhu":"Tiên khí dung hợp tinh hoa tiên kim","phamCap":"Vô Thượng chí bảo","soHuu":["Nữ tử áo trắng đeo mặt nạ quỷ"],"trangThai":"Nguyên vẹn","blurb":"Chí bảo của nữ tử áo trắng, lấy đồng thau bình thường làm gốc rồi dung nhập tinh hoa tiên kim. Vật này có thể biến đổi thành nhiều hình thái và hóa thành màn trời trấn áp đối thủ.","detail":"Mặt nạ có đường nét tựa khóc không khóc, tựa cười không cười và che giấu dung mạo người đeo. Nó lần lượt biến thành chiếc nhẫn, Tiên Kiếm và đại đạo bảo bình trước khi trở lại hình dạng mặt nạ; khi được ném ngược dòng thời gian, chí bảo phủ kín bầu trời, phá nát tinh đấu và trấn áp nam tử ở thượng du.","hinhDang":"Mặt nạ đồng xanh có đường nét tựa khóc không khóc, tựa cười không cười.","vatLieu":"Đồng thau bình thường dung nhập tinh hoa tiên kim.","nguonGoc":"Được cô đọng từ đồng thau rồi bổ sung tinh hoa tiên kim để thành chí bảo.","uyLuc":"Có thể phá nát tinh đấu, bao phủ bầu trời và tầng tầng trấn áp một cường giả ở thượng du dòng sông thời gian.","dacDiem":"Có thể biến thành chiếc nhẫn, Tiên Kiếm, đại đạo bảo bình rồi trở lại hình dạng mặt nạ.","chuHienThoi":"Nữ tử áo trắng đeo mặt nạ quỷ","capNhatToi":"@c1143","congNang":["Che giấu dung mạo của người đeo tại @c1143.","Biến đổi giữa mặt nạ, chiếc nhẫn, Tiên Kiếm và đại đạo bảo bình tại @c1143.","Hóa thành màn trời phá nát tinh đấu và trấn áp đối thủ tại @c1143.","Luyện hóa tinh huyết đã hấp thu.","Phóng tiên kiếp lực công kích đối thủ."],"chuSoHuu":[{"ten":"Nữ tử áo trắng đeo mặt nạ quỷ","tuChuong":"@c1143","denChuong":"","cachCoDuoc":"Chưa rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1143","loai":"dùng","importance":"normal","giaiDoan":"Hóa màn trời trấn áp","text":"Nữ tử áo trắng ném mặt nạ ngược dòng thời gian, khiến nó hóa thành màn trời phá vỡ tinh đấu và phủ xuống trấn áp nam tử ở thượng du.","anchor":"Này mặt nạ bằng đồng xanh đến quá nhanh, che ngợp bầu trời, đập vụn bầu trời trên tinh đấu, trực tiếp đem nam tử kia bao trùm ở phía dưới, tầng tầng trấn áp mà xuống!","phamCap":"Vô Thượng chí bảo"},{"chuong":"@c1145","loai":"dùng","importance":"normal","giaiDoan":"Luyện hóa tinh huyết","phamCap":"Chưa rõ","text":"Nữ tử áo trắng dùng bảo bình nung nấu tinh huyết của nam tử và phóng tiên kiếp lực đánh tan pháp thân hắn.","anchor":"Theo đại đạo bảo bình phun trào, cái kia quang vô cùng vô tận, đem trước kia nuốt lấy nam tử kia một thân tinh huyết đều nung nấu ở trong đó"}]},"nguon":["@c1143","@c1145"]},{"id":"tien-gia-chien-y-cua-nam-tu-giap-tru","name":"Tiên gia chiến y của nam tử giáp trụ","aliases":["Giáp trụ tiên kim"],"cn":"","category":"phap-bao","categoryLabel":"Chiến y","phanLoaiPhu":"Tiên gia chiến y","phamCap":"Không rõ","soHuu":["Nam tử như quân vương trong cổ miếu"],"chuHienThoi":"Nam tử như quân vương trong cổ miếu","trangThai":"Hư hỏng","blurb":"Tiên gia chiến y che phủ toàn thân và chiếc đuôi của nam tử giáp trụ. Nó từng chịu đòn trực diện từ Tiên Kiếm, nhưng bị chém nứt hàng trăm chỗ rồi hoàn toàn sụp vỡ dưới hào quang của bảo bình.","detail":"Đây là chiến y bằng tiên kim của nam tử giáp trụ, có kết cấu che phủ cả thân thể lẫn chiếc đuôi người mặc. Trong lúc giao phong, chiến y chịu kiếm khí trực diện từ Tiên Kiếm và bị chém mở tại hàng trăm vị trí, sau đó hoàn toàn sụp vỡ dưới hào quang của bảo bình. @c1144","hinhDang":"Giáp trụ che phủ toàn thân và chiếc đuôi.","vatLieu":"Tiên kim","uyLuc":"Có thể chịu kiếm khí trực diện từ Tiên Kiếm, nhưng bị chém mở tại hàng trăm vị trí rồi hoàn toàn sụp vỡ dưới hào quang của bảo bình. @c1144","dacDiem":"Chiến y bằng tiên kim, che phủ cả thân thể và chiếc đuôi của người mặc.","chuSoHuu":[{"ten":"Nam tử như quân vương trong cổ miếu","tuChuong":"@c1144","denChuong":"","cachCoDuoc":"","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1144","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Chiến y bị Tiên Kiếm chém mở tại hàng trăm vị trí rồi sụp vỡ dưới hào quang bảo bình.","anchor":"Đây là một cái hi thế tiên gia chiến y, nhưng là bây giờ lại bị chém mở ra","phamCap":"Không rõ"}]},"capNhatToi":"@c1144","nguon":["@c1144"],"congNang":["Che phủ, bảo vệ toàn thân và chiếc đuôi của người mặc.","Có thể chịu kiếm khí trực diện từ Tiên Kiếm trước khi bị phá hủy. @c1144"]},{"id":"manh-giap-tru-tien-kim","name":"Mảnh giáp trụ tiên kim","cn":"","aliases":["Tiên kim thiết","Mảnh chiến y"],"category":"nguyen-lieu","categoryLabel":"Tàn phiến pháp khí Tiên Đạo","phanLoaiPhu":"Mảnh vỡ chiến y","phamCap":"Tiên Đạo","soHuu":["Thạch Hạo"],"chuHienThoi":"Thạch Hạo","trangThai":"Vỡ thành mảnh","blurb":"Mảnh giáp trụ tiên kim là tàn phiến vỡ ra từ tiên gia chiến y của nam tử trong trận chiến trên dòng sông thời gian. Sau khi chiến y nổ tung, một số mảnh rơi xuống phế tích và được Thạch Hạo thu lấy để nghiên cứu.","detail":"Những mảnh tiên kim này vốn thuộc tiên gia chiến y của nam tử có pháp thân bị đánh tan trong trận chiến trên dòng sông thời gian. Chúng lưu giữ dấu vết chiến đấu cùng đạo vận từ cuộc quyết đấu giữa hai cường giả; Thạch Hạo thu lấy một số tàn phiến tại phế tích nhằm nghiên cứu và tìm kiếm cơ hội ngộ đạo. @c1145","hinhDang":"Những mảnh vỡ của chiến y tiên kim.","vatLieu":"Tiên kim","nguonGoc":"Vỡ ra từ tiên gia chiến y của nam tử trong trận chiến trên dòng sông thời gian.","uyLuc":"Bản thân tàn phiến chưa thể hiện năng lực công kích.","dacDiem":"Tàn phiến tiên kim của một bộ tiên gia chiến y, lưu giữ dấu vết chiến đấu và đạo vận của hai cường giả.","congNang":["Lưu giữ dấu vết cuộc chiến giữa các cường giả.","Có thể được nghiên cứu để tìm hiểu đạo vận của trận quyết đấu và tìm kiếm cơ hội ngộ đạo. @c1145"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1145","denChuong":"","cachCoDuoc":"Thu lấy từ phế tích sau khi giáp trụ tiên kim nổ tung.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1145","tabs":{"tienTrinh":[{"chuong":"@c1145","loai":"đổi chủ","importance":"major","giaiDoan":"Được Thạch Hạo thu lấy","phamCap":"Tiên Đạo","text":"Sau khi chiến y nổ tung, một số mảnh tiên kim rơi vào phế tích và được Thạch Hạo thu lấy để nghiên cứu.","anchor":"đây là hai đại Chí Cường giả quyết đấu sau lưu lại \"Dấu vết\", ghi chép bọn họ chiến đấu rầm rộ"}]},"nguon":["@c1145"]},{"id":"binh-ruou-van-co","name":"Bình rượu vạn cổ","cn":"","aliases":[],"category":"khac","categoryLabel":"Vật phẩm","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Rượu đã cạn","blurb":"Bình rượu Thạch Hạo uống bên dòng sông thời gian, chứa rượu dịch có kinh văn và phù văn. Khi rượu cạn, những dấu vết này cũng nhạt dần rồi biến mất.","detail":"Rượu trong bình phát ra thần quang và các ký hiệu khi được uống. Kinh văn ẩn trong rượu từng hiện lên trong lòng Thạch Hạo nhưng sau đó tiêu tán, không để lại chứng cứ rõ ràng về trải nghiệm trên dòng sông thời gian.","phanLoaiPhu":"Bình chứa tiên nhưỡng","dacDiem":"Rượu dịch phát ra thần quang cùng nhiều ký hiệu, nhưng hương vị và kinh văn đều tiêu tán khi uống cạn.","chuHienThoi":"Thạch Hạo","congNang":["Chứa rượu dịch mang kinh văn và phù văn có thể hiện lên trong lòng người uống."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1146","denChuong":"@c1146","cachCoDuoc":"Uống tại bàn đá bên dòng sông thời gian","trangThai":"Đã uống cạn"}],"tabs":{"tienTrinh":[{"chuong":"@c1146","loai":"dùng","importance":"normal","giaiDoan":"Uống cạn","text":"Thạch Hạo uống hết rượu trong bình, sau đó các phù văn, kinh văn và hương vị đều dần tiêu tán.","anchor":"nơi này thần quang lóng lánh các loại ký hiệu toát ra, chính là đến cuối cùng cả bầu rượu đều dần dần đã không có hương vị"}]},"capNhatToi":"@c1146","nguon":["@c1146"]},{"id":"bach-ky-lan-au-thu","name":"Bạch kỳ lân ấu thú","cn":"","aliases":["Kỳ Lân con non"],"category":"khac","categoryLabel":"Linh thú","phamCap":"Không rõ","soHuu":["Thái Âm Ngọc Thỏ"],"trangThai":"Còn sống","blurb":"Kỳ lân con chỉ nhận Thái Âm Ngọc Thỏ, người khác không thể mang đi. Nó bị nàng ném ra đập nhóm thứ đầu khi xảy ra xung đột.","detail":"Bạch kỳ lân ấu thú được Thái Âm Ngọc Thỏ ôm trong ngực và dùng như vật ném khi nàng tức giận. Các đệ tử không dám làm nó bị thương vì đại trưởng lão Thiên Thần thư viện từng nghiêm cấm việc tổn hại kỳ lân con.","phanLoaiPhu":"Kỳ lân ấu thú","chuHienThoi":"Thái Âm Ngọc Thỏ","chuSoHuu":[{"ten":"Thái Âm Ngọc Thỏ","tuChuong":"@c1146","denChuong":"","cachCoDuoc":"Bạch kỳ lân tự nhận nàng","trangThai":"Đi theo"}],"tabs":{"tienTrinh":[{"chuong":"@c1146","loai":"dùng","importance":"normal","giaiDoan":"Bị ném vào đối phương","text":"Bạch kỳ lân ấu thú bị Thái Âm Ngọc Thỏ ném ra đập người trong lúc nàng giằng co với nhóm thứ đầu.","anchor":"con bạch kỳ lân ấu thú kia còn cũng chỉ nhận thức chuẩn tiểu cô nương kia, ai đều mang không đi"}]},"capNhatToi":"@c1146","nguon":["@c1146"]},{"id":"bat-diet-tien-dan","name":"Bất diệt tiên đan","cn":"","aliases":[],"category":"dan-duoc","categoryLabel":"Đan dược","phanLoaiPhu":"Tiên Đạo đại dược","phamCap":"Tiên Đạo","soHuu":[],"trangThai":"Đã bay khỏi lò luyện đan","blurb":"Một viên Tiên Đạo đại dược có sinh mệnh, từng ẩn trong lò luyện đan rồi tự bay đi khi bị phát hiện. Tro thuốc còn sót lại cũng đủ giúp người ăn hoàn thành một lần lột xác.","detail":"Bất diệt tiên đan có khả năng tự phi thiên độn địa và tỏa ra hương thơm khi bay khỏi lò. Nó được nhắc đến như đại dược có thể hỗ trợ con đường chứng bất tử.","congNang":["Hỗ trợ chứng bất tử chi đạo.","Tro thuốc còn sót lại có thể giúp người dùng hoàn thành một lần lột xác."],"uyLuc":"Tro thuốc còn lại sau khi tiên đan rời đi vẫn mang lại một lần lột xác.","dacDiem":"Có sinh mệnh và có thể tự bay khỏi nơi cất giữ.","capNhatToi":"@c1148","tabs":{"tienTrinh":[{"chuong":"@c1148","loai":"xuất hiện","importance":"normal","giaiDoan":"Bay khỏi lò luyện đan","text":"Bất diệt tiên đan phát sáng rồi tự bay khỏi lò khi người phát hiện định ra tay thu lấy.","anchor":"nó là có sinh mệnh, vút qua không trung, mang theo thơm ngát","phamCap":"Tiên Đạo"}]},"nguon":["@c1148"]},{"id":"co-lao-chien-thuyen","name":"Cổ lão chiến thuyền","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Phương tiện","phanLoaiPhu":"Chiến thuyền vượt vũ trụ","phamCap":"Không rõ","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Đang hoạt động","blurb":"Một chiến thuyền khổng lồ dùng để chuyên chở đoàn người của Thiên Thần Thư Viện. Nó vượt qua vũ trụ và các Ngân hà để đưa những người sống sót trở về Vô Lượng Thiên.","detail":"Sau khi tế đàn ngừng tiếp nhận người trở về, các trưởng lão dẫn đoàn người lên cổ lão chiến thuyền. Chiến thuyền rời hòn đảo, vượt tinh không và hoàn tất hành trình về Thiên Thần Thư Viện.","congNang":["Chuyên chở một đoàn người vượt qua vũ trụ và các Ngân hà."],"dacDiem":"Có kích thước khổng lồ và khả năng vượt tinh không.","chuHienThoi":"Thiên Thần Thư Viện","chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1148","denChuong":"","cachCoDuoc":"Phương tiện do thư viện điều động","trangThai":"đang sở hữu"}],"capNhatToi":"@c1148","tabs":{"tienTrinh":[{"chuong":"@c1148","loai":"dùng","importance":"normal","giaiDoan":"Đưa đoàn người trở về","text":"Cổ lão chiến thuyền chở những người sống sót vượt vũ trụ trở lại Vô Lượng Thiên và Thiên Thần Thư Viện.","anchor":"to lớn chiến thuyền vượt qua vũ trụ, mang theo một đám người đi xa","phamCap":"Không rõ"}]},"nguon":["@c1148"]},{"id":"dai-dao-chi-chung","name":"Đại đạo chi chung","cn":"","category":"phap-bao","categoryLabel":"Chuông triệu tập","phamCap":"","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Đang được sử dụng","blurb":"Đại chung ẩn trong sương mù Hỗn Độn, có tiếng chuông vang trực tiếp trong tâm thần mọi người.","detail":"Thiên Thần Thư Viện dùng tiếng chuông để triệu tập quần anh tới Thạch Lâm nghe các trưởng lão công bố việc truyền tiên đạo kinh văn và lựa chọn con đường tu hành.","hinhDang":"Đại chung ẩn trong sương mù Hỗn Độn","dacDiem":"Tiếng chuông vang trực tiếp trong nội tâm người nghe.","chuHienThoi":"Thiên Thần Thư Viện","congNang":["Triệu tập các cường giả và học viên của Thiên Thần Thư Viện."],"chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1154","denChuong":"","cachCoDuoc":"","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1154","tabs":{"tienTrinh":[{"chuong":"@c1154","loai":"dùng","importance":"normal","giaiDoan":"Triệu tập quần anh","text":"Đại đạo chi chung vang trong tâm thần mọi người, triệu tập họ tới nghe các trưởng lão công bố lựa chọn con đường tu hành.","anchor":"Đây là đại đạo chi chung, tuyên truyền giác ngộ, trực tiếp vang ở tất cả mọi người trong nội tâm","phamCap":""}]},"nguon":["@c1154"]},{"id":"kinh-thu-va-tien-kinh-ky-nguyen-truoc","name":"Kinh thư và tiên kinh kỷ nguyên trước","cn":"","category":"khac","categoryLabel":"Đạo thư","phamCap":"Tiên cổ vô thượng đạo thư và tiên kinh","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Được lưu giữ và truyền thừa","blurb":"Kho đạo thư và tiên kinh có nguồn gốc từ kỷ nguyên trước do Thiên Thần Thư Viện nắm giữ. Đây là tài nguyên truyền thừa dành cho học viên lựa chọn Tiên cổ pháp.","detail":"Các kinh thư cung cấp nền tảng tu luyện cổ pháp trong thời đại hiện tại. Thiên Thần Thư Viện xem chúng là một trong những điều kiện chủ yếu để hỗ trợ học viên đi theo con đường Tiên cổ.","nguonGoc":"Kỷ nguyên trước","chuHienThoi":"Thiên Thần Thư Viện","dacDiem":"Bao gồm Tiên cổ vô thượng đạo thư và tiên kinh.","congNang":["Cung cấp truyền thừa tu luyện cho người lựa chọn Tiên cổ pháp."],"chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1155","denChuong":"","cachCoDuoc":"Được thư viện lưu giữ làm truyền thừa","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1155","loai":"xuất hiện","importance":"normal","giaiDoan":"Công bố tài nguyên truyền thừa","text":"Các trưởng lão cho biết Thiên Thần Thư Viện có đạo thư và tiên kinh từ kỷ nguyên trước dành cho người chọn Tiên cổ pháp.","anchor":"Nơi này có Tiên cổ vô thượng đạo thư, thậm chí là tiên kinh, chúng ta nếu là tu luyện, thành thì sẽ không thấp."}]},"capNhatToi":"@c1155","nguon":["@c1155"]},{"id":"bach-ngoc-son-khac-chu-co","name":"Bạch ngọc sơn khắc chữ cổ","cn":"","aliases":["Ngọc thạch sơn Tiên cổ"],"category":"khac","categoryLabel":"Vật phẩm tham ngộ","phanLoaiPhu":"Núi ngọc khắc đạo văn","phamCap":"Di vật Tiên cổ","soHuu":["Bốn trưởng lão"],"trangThai":"Còn tồn tại nhưng mất phần đỉnh","blurb":"Một ngọn núi ngọc từ Tiên cổ kỷ nguyên, trên vách khắc không dưới trăm vạn chữ cổ. Phần đỉnh chứa 108 chữ quan trọng đã bị tước mất.","detail":"Bốn trưởng lão lấy vật này từ trong tay áo rồi phóng lớn thành một ngọn núi trong khu di tích. Học viên được yêu cầu nghiên cứu các chữ cổ phủ kín vách núi để bắt đầu tham ngộ Tiên cổ pháp.","hinhDang":"Ngọn núi bằng bạch ngọc có vách phủ kín chữ cổ và phần đỉnh bị mất.","vatLieu":"Bạch ngọc","nguonGoc":"Di vật lưu lại từ Tiên cổ kỷ nguyên","uyLuc":"Bản thân ngọn núi lưu giữ hệ thống trăm vạn chữ phục vụ việc lĩnh ngộ quy tắc và đạo lý Tiên cổ.","dacDiem":"Khắc không dưới trăm vạn chữ cổ; phần đỉnh từng chứa 108 chữ cô đọng chân nghĩa đại đạo.","chuHienThoi":"Bốn trưởng lão","capNhatToi":"@c1156","congNang":["Cung cấp trăm vạn chữ cổ để người học nghiên cứu và tham ngộ văn tự Tiên cổ."],"chuSoHuu":[{"ten":"Bốn trưởng lão","tuChuong":"@c1156","denChuong":"","cachCoDuoc":"Được lấy ra từ trong tay áo để dùng trong buổi giảng.","trangThai":"Đang quản lý"}],"tabs":{"tienTrinh":[{"chuong":"@c1156","loai":"xuất hiện","importance":"normal","giaiDoan":"Đưa ra làm vật tham ngộ","text":"Bốn trưởng lão phóng lớn bạch ngọc sơn và đặt nó tại khu di tích để học viên nghiên cứu trăm vạn chữ cổ.","anchor":"Đây là Tiên cổ kỷ nguyên lưu lại một toà ngọc thạch sơn","phamCap":"Di vật Tiên cổ"}]},"nguon":["@c1156"]},{"id":"mot-tram-le-tam-chu-co-tren-dinh-bach-ngoc-son","name":"Một trăm lẻ tám chữ cổ trên đỉnh bạch ngọc sơn","cn":"","aliases":["108 chữ cổ trên đỉnh bạch ngọc sơn"],"category":"khac","categoryLabel":"Chân ngôn thất truyền","phanLoaiPhu":"Bộ chữ cô đọng đại đạo chân nghĩa","phamCap":"Chân ngôn Tiên cổ","soHuu":[],"trangThai":"Thất truyền","blurb":"Một trăm lẻ tám chữ cổ từng được khắc trên phần đỉnh bạch ngọc sơn có từ Tiên cổ kỷ nguyên. Mỗi chữ đều cô đọng chân nghĩa đại đạo, được truyền là mang sức mạnh kinh thiên động địa, nhưng đã thất truyền cùng phần đỉnh núi.","detail":"Bộ 108 chữ cổ vốn nằm trên phần đỉnh của bạch ngọc sơn từ Tiên cổ kỷ nguyên. Sau khi phần đỉnh núi bị tước mất, toàn bộ những chữ cổ quan trọng này cũng biến mất, không còn chữ nào được lưu truyền tại ngọn núi. Theo lời bốn trưởng lão, mỗi chữ đều cô đọng chân nghĩa đại đạo; chỉ cần nắm giữ một chữ cũng có thể thu được sức mạnh và lợi ích rất lớn. @c1156","hinhDang":"Một bộ gồm 108 chữ cổ từng được khắc trên đỉnh bạch ngọc sơn.","nguonGoc":"Phần đỉnh bạch ngọc sơn từ Tiên cổ kỷ nguyên","uyLuc":"Mỗi chữ cổ được truyền là có sức mạnh kinh thiên động địa.","dacDiem":"Gồm 108 chữ cổ khắc trên phần đỉnh bạch ngọc sơn từ Tiên cổ kỷ nguyên, về sau thất truyền cùng phần đỉnh núi.","capNhatToi":"@c1156","congNang":["Cô đọng chân nghĩa đại đạo trong từng chữ cổ. @c1156","Người nắm giữ dù chỉ một chữ cũng có thể thu được sức mạnh và lợi ích lớn. @c1156"],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1156","loai":"nhắc tới","importance":"major","giaiDoan":"Công bố tình trạng thất truyền","text":"Bốn trưởng lão tiết lộ 108 chữ cổ cô đọng chân nghĩa đại đạo từng nằm trên phần đỉnh bạch ngọc sơn nhưng nay đều đã thất truyền.","anchor":"108 cái chữ cổ là cô đọng đại đạo chân nghĩa","phamCap":"Chân ngôn Tiên cổ"}]},"nguon":["@c1156"]},{"id":"cay-non-the-gioi-thu-cua-thap-quan-vuong","name":"Cây non Thế Giới Thụ của Thập Quan Vương","cn":"","aliases":["Cây non Thế Giới Thụ","Vô Thượng Tiên đạo Bảo Thụ"],"category":"khac","categoryLabel":"Tiên chủng","phamCap":"Một trong những tiên chủng tốt nhất","soHuu":["Thập Quan Vương"],"trangThai":"Đang thuộc Thập Quan Vương","blurb":"Cây non Thế Giới Thụ là tiên chủng tuyệt thế thuộc về Thập Quan Vương. Khi được công khai sử dụng trên Bạch Ngọc Sơn, bảo thụ tỏa Hỗn Độn Khí cùng vô số đạo quang, hỗ trợ hắn lĩnh ngộ số lượng lớn chữ cổ.","detail":"Cây non Thế Giới Thụ được Thập Quan Vương công khai triển lộ trên Bạch Ngọc Sơn để hỗ trợ lĩnh ngộ chữ cổ. Tứ trưởng lão xác nhận loại Vô Thượng Tiên đạo Bảo Thụ này không thể che giấu, đồng thời xếp nó vào hàng những tiên chủng tốt nhất. @c1157","phanLoaiPhu":"Vô Thượng Tiên đạo Bảo Thụ","hinhDang":"Cây nhỏ","uyLuc":"Quét ra hàng ngàn, hàng vạn đạo quang giữa Hỗn Độn Khí.","dacDiem":"Tiên chủng tuyệt thế thuộc hàng tốt nhất.","chuHienThoi":"Thập Quan Vương","congNang":["Tỏa Hỗn Độn Khí và hàng ngàn, hàng vạn đạo quang, hỗ trợ Thập Quan Vương lĩnh ngộ số lượng lớn chữ cổ. @c1157"],"chuSoHuu":[{"ten":"Thập Quan Vương","tuChuong":"@c1157","denChuong":"","cachCoDuoc":"Chưa được tiết lộ trong chương","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1157","tabs":{"tienTrinh":[{"chuong":"@c1157","loai":"xuất hiện","importance":"major","giaiDoan":"Công khai hiển lộ","text":"Cây non Thế Giới Thụ công khai xuất hiện trong tay Thập Quan Vương và hỗ trợ hắn lĩnh ngộ số lượng lớn chữ cổ.","anchor":"loại này Vô Thượng Tiên đạo Bảo Thụ căn bản là không giấu được","phamCap":"Một trong những tiên chủng tốt nhất"}]},"nguon":["@c1157"]},{"id":"mo-hinh-vu-tru-cua-trich-tien","name":"Mô hình vũ trụ của Trích Tiên","cn":"","aliases":["Mô hình vũ trụ cổ"],"category":"khac","categoryLabel":"Tiên chủng chưa được xác nhận","phamCap":"Có khả năng thuộc hàng tiên chủng tốt nhất","soHuu":["Trích Tiên"],"trangThai":"Chưa xác nhận dứt khoát là tiên chủng","blurb":"Một mô hình vũ trụ cổ hiện ra quanh Trích Tiên khi hắn chịu áp lực từ mấy nghìn chữ cổ. Tứ trưởng lão nghi đây là tiên chủng của hắn nhưng chưa đưa ra kết luận.","detail":"Dị tượng diễn hóa giữa Hỗn Độn Khí và hiện ra như một vùng vũ trụ cổ. Phần giảng giải sau đó xếp mô hình vũ trụ vào nhóm tiên chủng tốt nhất, song công năng cụ thể của vật này chưa được tiết lộ.","phanLoaiPhu":"Tiên chủng nghi vấn","hinhDang":"Một vùng vũ trụ mô hình đang diễn hóa","dacDiem":"Hiện ra giữa Hỗn Độn Khí khi Trích Tiên chịu áp lực từ chữ cổ.","chuHienThoi":"Trích Tiên","chuSoHuu":[{"ten":"Trích Tiên","tuChuong":"@c1157","denChuong":"","cachCoDuoc":"Chưa rõ","trangThai":"Quan hệ sở hữu chưa được xác nhận dứt khoát"}],"capNhatToi":"@c1157","tabs":{"tienTrinh":[{"chuong":"@c1157","loai":"xuất hiện","importance":"normal","giaiDoan":"Lần đầu hiện ra","text":"Mô hình vũ trụ xuất hiện giữa Hỗn Độn Khí khi Trích Tiên bị mấy nghìn chữ cổ áp bức, khiến Tứ trưởng lão nghi đây là tiên chủng của hắn.","anchor":"đây là mấy ngàn chữ cổ áp bức mà dẫn đến tiên chủng hiện ra sao?","phamCap":"Tiên chủng chưa được xác nhận"}]},"nguon":["@c1157"]},{"id":"lo-luyen-dan-tien-co-bang-da","name":"Lò luyện đan Tiên Cổ bằng đá","aliases":[],"cn":"","category":"phap-bao","categoryLabel":"Lò luyện đan","phamCap":"Không phải Vô Thượng bảo cụ","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Tàn tạ","blurb":"Lò đá được Thiên Thần Thư Viện đào từ một động phủ tiên gia và chuyển tới Bạch Ngọc Sơn.","detail":"Lò có hình dạng như một ngọn núi đá hình lò lửa, từng dùng để luyện Tiên Đan. Tro tàn bên trong vẫn lưu dược tính và chôn một số Phạt Mạch đan.","phanLoaiPhu":"Lò luyện đan Tiên Cổ","hinhDang":"Ngọn núi đá có hình lò lửa.","vatLieu":"Đá","nguonGoc":"Được đào từ một động phủ tiên gia.","uyLuc":"Dược tính còn sót lại có thể đánh thức bảo đan bị chôn trong tro lò.","dacDiem":"Từng luyện Tiên Đan nhưng hiện đã tàn tạ.","chuHienThoi":"Thiên Thần Thư Viện","congNang":["Từng dùng để luyện Tiên Đan và lưu giữ dược tính trong tro tàn."],"chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1159","denChuong":"","cachCoDuoc":"Đào được từ động phủ tiên gia.","trangThai":"đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1159","loai":"xuất hiện","importance":"normal","giaiDoan":"Mở cơ duyên tranh đan","text":"Tứ trưởng lão chuyển lò đá tới Bạch Ngọc Sơn và đánh thức dược tính còn lại để mở cuộc tranh Phạt Mạch đan.","anchor":"Tuy rằng không phải cái gì Vô Thượng Bảo cụ, nhưng thật sự luyện quá Tiên Đan","phamCap":"Không phải Vô Thượng bảo cụ"}]},"capNhatToi":"@c1159","nguon":["@c1159"]},{"id":"phat-mach-dan","name":"Phạt Mạch đan","aliases":[],"cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Bảo đan","soHuu":[],"trangThai":"Chôn trong tro lò","blurb":"Đan dược quan trọng đối với người tu Tiên Cổ pháp, còn sót lại trong tro của lò luyện đan Tiên Cổ.","detail":"Phạt Mạch đan có thể sắp xếp thân thể và giảm trở ngại khi tu Tiên Cổ pháp. Số lượng đan còn lại có hạn nên các đệ tử phải dùng thực lực tranh giành.","phanLoaiPhu":"Đan dược hỗ trợ tu luyện","nguonGoc":"Được chôn trong tro của lò luyện đan từng luyện Tiên Đan.","dacDiem":"Số lượng có hạn và được phân phối bằng tranh đấu thực lực.","congNang":["Sắp xếp thân thể và giảm trở ngại khi tu Tiên Cổ pháp."],"tabs":{"tienTrinh":[{"chuong":"@c1159","loai":"xuất hiện","importance":"normal","giaiDoan":"Cơ duyên tại Bạch Ngọc Sơn","text":"Phạt Mạch đan được phát hiện còn chôn trong tro lò và trở thành mục tiêu tranh đoạt của các đệ tử.","anchor":"chính là tu luyện Tiên Cổ pháp muốn dùng đến một loại phi thường trọng yếu phạt mạch đan","phamCap":"Bảo đan"}]},"capNhatToi":"@c1159","nguon":["@c1159"]},{"id":"khong-minh-kinh-do-nhai","name":"Không Minh kính đồ nhái","cn":"","aliases":["Cốt kính"],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thanh niên đội Tử Kim quan"],"trangThai":"hong","blurb":"Bảo kính đồ nhái có thể thu nạp bảo thuật đối phương rồi phóng ngược lại, cốt kính mài từ xương Kim Ô, bị Mạc Đạo đánh vỡ.","detail":"Bảo kính có khả năng dung nạp công kích đối phương vào trong rồi phóng thích trả lại. Bản thân cốt kính được mài từ xương Kim Ô huyết thống chưa đủ mạnh nên còn có thể phát ra Kim Ô. Bên trong giấu một đoản kiếm dùng để ám kích khi kính vỡ. Bị Mạc Đạo áp sát cận chiến và đánh vỡ.","hinhDang":"Tấm gương","vatLieu":"Xương Kim Ô","congNang":["Thu nạp bảo thuật đối phương rồi phóng ngược trở lại","Phát ra Kim Ô từ cốt kính"],"chuSoHuu":[{"ten":"Thanh niên đội Tử Kim quan","tuChuong":"@c1160","denChuong":"","cachCoDuoc":"","trangThai":"hong"}],"tabs":{"tienTrinh":[{"chuong":"@c1160","loai":"dùng","importance":"normal","giaiDoan":"Sử dụng trong trận chiến với Mạc Đạo","text":"Thu nạp Hỏa Hoàng do Mạc Đạo diễn hóa rồi phóng ngược, đồng thời phát Kim Ô từ cốt kính, nhưng bị Mạc Đạo áp sát đánh vỡ.","anchor":"có thể đem công kích của đối phương dung nạp nhập kính trong cơ thể, rồi sau đó lại phóng thích"}]},"capNhatToi":"@c1160","nguon":["@c1160"]},{"id":"doan-kiem-giau-trong-khong-minh-kinh","name":"Đoản kiếm giấu trong Không Minh kính","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thanh niên đội Tử Kim quan"],"trangThai":"hong","blurb":"Đoản kiếm ẩn bên trong Không Minh kính, bay ra khi kính vỡ để ám kích Mạc Đạo nhưng bị lợi khí hình long xà chặt đứt.","detail":"Đoản kiếm giấu trong bảo kính, khi kính vỡ thì tự bay ra hóa thành sắc bén thần mang nhằm bất ngờ chém Mạc Đạo. Bị lợi khí hình long xà của Mạc Đạo chặt đứt.","congNang":["Ám kích bất ngờ từ bên trong bảo kính khi kính vỡ"],"chuSoHuu":[{"ten":"Thanh niên đội Tử Kim quan","tuChuong":"@c1160","denChuong":"","cachCoDuoc":"","trangThai":"hong"}],"tabs":{"tienTrinh":[{"chuong":"@c1160","loai":"dùng","importance":"normal","giaiDoan":"Ám kích Mạc Đạo","text":"Bay ra từ trong gương khi Không Minh kính vỡ, hóa thần mang chém về phía Mạc Đạo nhưng bị chặt đứt.","anchor":"một ngụm đoản kiếm theo trong gương bay ra, hóa thành sắc bén thần mang"}]},"capNhatToi":"@c1160","nguon":["@c1160"]},{"id":"loi-khi-hinh-long-xa-cua-mac-dao","name":"Lợi khí hình long xà của Mạc Đạo","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Mạc Đạo"],"trangThai":"dang-co","blurb":"Binh khí hình long xà vô cùng sắc bén mà Mạc Đạo dùng để chặt đứt đoản kiếm và chém ngang lưng thanh niên đội Tử Kim quan.","detail":"Lợi khí hình dạng long xà, được mô tả là vô kiên bất tồi. Mạc Đạo dùng nó chặt gãy đoản kiếm rồi chém ngang lưng đối thủ.","hinhDang":"Hình long xà","congNang":["Binh khí cận chiến sắc bén, vô kiên bất tồi"],"chuSoHuu":[{"ten":"Mạc Đạo","tuChuong":"@c1160","denChuong":"","cachCoDuoc":"","trangThai":"dang-co"}],"tabs":{"tienTrinh":[{"chuong":"@c1160","loai":"dùng","importance":"normal","giaiDoan":"Dùng chém thanh niên đội Tử Kim quan","text":"Mạc Đạo dùng lợi khí hình long xà chặt đứt đoản kiếm rồi chém ngang lưng thanh niên đội Tử Kim quan.","anchor":"Mạc Đạo cầm trong tay một thanh lợi khí, giống nhau long xà, vô kiên bất tồi"}]},"capNhatToi":"@c1160","nguon":["@c1160"]},{"id":"thanh-dong-khoi-loi","name":"Thanh đồng khôi lỗi","cn":"","aliases":["Thanh đồng nhân"],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Kẻ điều khiển thanh đồng khôi lỗi"],"trangThai":"hong","blurb":"Chiến tranh công cụ hình người bằng thanh đồng pha một phần tiên kim, được kẻ ẩn danh điều khiển để thăm dò Thạch Hạo nhưng bị hắn tay không xé nát.","detail":"Khôi lỗi hình người bằng thanh đồng, thân thể chứa thần liệu và pha một phần tiên kim. Được điều khiển từ xa để tấn công Thạch Hạo, cánh tay bị quyền đánh lõm rồi toàn thân bị xé thành mảnh nhỏ.","vatLieu":"Thanh đồng, một phần tiên kim","congNang":["Chiến tranh công cụ hình người, chiến đấu thay chủ nhân"],"chuSoHuu":[{"ten":"Kẻ điều khiển thanh đồng khôi lỗi","tuChuong":"@c1160","denChuong":"","cachCoDuoc":"","trangThai":"hong"}],"tabs":{"tienTrinh":[{"chuong":"@c1160","loai":"dùng","importance":"normal","giaiDoan":"Thăm dò Thạch Hạo","text":"Bị kẻ ẩn danh tế ra tấn công Thạch Hạo, cánh tay bị quyền đánh lõm rồi toàn thân bị tay không xé thành mảnh nhỏ.","anchor":"kể cả cái kia thanh đồng nhân, tức thì bị Thạch Hạo tay không xé thành mảnh nhỏ"}]},"capNhatToi":"@c1160","nguon":["@c1160"]},{"id":"bi-bao-truong-sinh-gia-toc","name":"Bí bảo do Trường Sinh gia tộc ban xuống","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thái Cổ mãng ngưu hóa hình","Phi Thiên Ngô Công hóa hình","Ba đầu Vua Sư Tử hóa hình","Ngân quy hóa hình"],"trangThai":"hong","blurb":"Nhóm bí bảo do các Trường Sinh gia tộc ban cho bốn sinh linh để vây công Thạch Hạo, nhưng toàn bộ đều bị nhục thân hắn phá hủy.","detail":"Các bí bảo xuất từ Trường Sinh gia tộc, được bốn sinh linh sử dụng khi vây đánh Thạch Hạo nhằm ép hắn bộc lộ pháp lực. Tất cả đều bạo nát trong những cuộc va chạm trực diện với nhục thân hắn.","nguonGoc":"Trường Sinh gia tộc ban xuống","congNang":["Bí bảo chiến đấu dùng để thăm dò đối thủ"],"tabs":{"tienTrinh":[{"chuong":"@c1160","loai":"dùng","importance":"normal","giaiDoan":"Bị phá hủy khi vây công Thạch Hạo","text":"Bốn sinh linh mang bí bảo Trường Sinh gia tộc vây đánh Thạch Hạo, toàn bộ đều bạo nát khi va chạm với nhục thân hắn.","anchor":"tuy nhiên xuất từ Trường Sinh gia tộc, nhưng là tại liên tiếp va chạm mạnh ở bên trong, hay là bạo nát"}]},"capNhatToi":"@c1160","nguon":["@c1160"]},{"id":"kiem-thai-hac-am-tien-kim-cua-vuong-hi","name":"Kiếm thai Hắc Ám tiên kim của Vương Hi","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Kiếm thai","phanLoaiPhu":"Bí bảo","phamCap":"Không rõ","soHuu":["Vương Hi"],"trangThai":"Đang do Vương Hi nắm giữ","blurb":"Thanh kiếm màu đen phát ra ánh sáng nhiều màu và chứa một lượng Hắc Ám tiên kim.","detail":"Kiếm thai là bí bảo quan trọng do Vương gia trao cho Vương Hi. Thạch Hạo nhận ra bên trong thanh kiếm có một lượng Hắc Ám tiên kim và cân nhắc dùng Đại La tiên kiếm phá hủy nó để thu lấy tinh hoa.","hinhDang":"Thanh kiếm màu đen phát ra ánh sáng nhiều màu.","vatLieu":"Chứa một lượng Hắc Ám tiên kim.","dacDiem":"Bề ngoài màu đen nhưng tỏa ánh sáng nhiều màu.","chuHienThoi":"Vương Hi","congNang":["Được Vương Hi dùng làm binh khí tấn công Thạch Hạo."],"chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1161","denChuong":"","cachCoDuoc":"Được Vương gia ban cho","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1161","tabs":{"tienTrinh":[{"chuong":"@c1161","loai":"xuất hiện","importance":"normal","giaiDoan":"Giao chiến với Thạch Hạo","text":"Vương Hi lấy ra kiếm thai màu đen phát ánh sáng nhiều màu, để lộ bên trong có một lượng Hắc Ám tiên kim.","phamCap":"Không rõ","anchor":"nàng thanh kiếm này thai ẩn chứa một số ít tiên kim"}]},"nguon":["@c1161"]},{"id":"canh-mau-vang-tu-hu-khong","name":"Cành màu vàng từ hư không","cn":"","category":"khac","categoryLabel":"Vật triệu hiện","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Những cành màu vàng bất ngờ sinh trưởng từ hư không sau cuộc đối đầu thiên công giữa Thạch Hạo và Vương Hi.","detail":"Các cành có độ cứng cỏi đủ sức chống lại hắc ám tiên kim kiếm. Phù hiệu xuất hiện trên thân cành giúp chúng liên tục siết chặt, trói buộc Vương Hi và cầm cố nàng giữa hư không.","phanLoaiPhu":"Vật triệu hiện chưa rõ nguồn gốc","hinhDang":"Những cành màu vàng mang phù hiệu","uyLuc":"Chịu được sự chém phá của tiên kim kiếm và khiến Vương Hi không thể giãy thoát.","dacDiem":"Mọc trực tiếp từ hư không, có màu vàng và xuất hiện phù hiệu khi siết mục tiêu.","chuHienThoi":"Thạch Hạo","congNang":["Trói buộc mục tiêu bằng những cành mang phù hiệu.","Cầm cố mục tiêu giữa hư không."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1162","denChuong":"","cachCoDuoc":"Triệu hiện trong trận chiến","trangThai":"đang-co"}],"capNhatToi":"@c1162","tabs":{"tienTrinh":[{"chuong":"@c1162","loai":"dùng","importance":"normal","giaiDoan":"Trói giữ Vương Hi","text":"Những cành màu vàng mọc từ hư không, chống lại tiên kim kiếm rồi dùng phù hiệu trói chặt Vương Hi.","anchor":"màu vàng cành liễu thiên cứng cỏi, có một ít che ở trên người nàng","phamCap":"Không rõ"}]},"nguon":["@c1162"]},{"id":"manh-dan-duoc-lon-nhu-rang-rong","name":"Mảnh đan dược lớn như răng rồng","cn":"","category":"dan-duoc","categoryLabel":"Mảnh đan dược","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Còn tồn tại","blurb":"Mảnh đan dược cổ lớn như răng rồng, mang hoa văn phức tạp và thần bí. Thạch Hạo nghi đây là tàn phiến của Cửu Chuyển Tiên Đan.","detail":"Thạch Hạo dùng Võ đạo Thiên nhãn tìm được một nơi tiên khí mông lung trong tro dược rồi đào ra mảnh đan này. Lai lịch và công dụng chưa được xác nhận.","phanLoaiPhu":"Mảnh tiên đan nghi vấn","hinhDang":"Lớn như răng rồng, bề mặt có hoa văn phức tạp.","dacDiem":"Tỏa vẻ thần bí và được nghi có liên quan đến Cửu Chuyển Tiên Đan.","chuHienThoi":"Thạch Hạo","chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1164","denChuong":"","cachCoDuoc":"Đào được tại nơi tiên khí mông lung trong thạch lô.","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1164","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện","text":"Thạch Hạo đào được mảnh đan lớn như răng rồng có hoa văn phức tạp và nghi nó thuộc Cửu Chuyển Tiên Đan.","anchor":"Hắn tìm kiếm một mảnh Long Nha đại đan dược mảnh vỡ, mặt trên có phiền phức hoa văn","phamCap":"Chưa rõ"}]},"capNhatToi":"@c1164","nguon":["@c1164"]},{"id":"dan-duoc-xen-lan-am-kim","name":"Đan dược xen lẫn ám kim","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Còn linh tính, được cất trong bình ngọc","blurb":"Mảnh đan ám kim sinh ra xen lẫn trong quá trình luyện vô thượng tiên đan.","detail":"Mảnh đan vẫn còn hương thơm và linh tính sau thời gian dài. Tuy không sánh được với tiên đan chân chính, nó vẫn có thể phạt mao tẩy tủy cho tu sĩ.","phanLoaiPhu":"Đan xen lẫn","hinhDang":"Mảnh đan màu ám kim","dacDiem":"Có cảm giác kim loại, hương thơm, linh tính và dấu vết đại đạo.","chuHienThoi":"Thạch Hạo","congNang":["Phạt mao tẩy tủy cho tu sĩ @c1165"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1165","denChuong":"","cachCoDuoc":"Tìm thấy trong tro tàn của thạch lô","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1165","loai":"xuất hiện","importance":"normal","giaiDoan":"Được nhận diện và thu giữ","text":"Mạc Đạo nhận ra đây là đan xen lẫn khi luyện vô thượng tiên đan, sau đó Thạch Hạo cất mảnh đan vào bình ngọc.","anchor":"tuy nhiên không có thể so đo chính thức Tiên Đan, nhưng là đối với tu sĩ mà nói cũng phi thường hi trân, có thể phạt mao tẩy tủy"}]},"capNhatToi":"@c1165","nguon":["@c1165"]},{"id":"manh-co-dan-trang","name":"Mảnh cổ đan trắng","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Thạch Hạo đã dùng một trong ba mảnh đoạt được","blurb":"Mảnh cổ đan trắng là phần còn sót lại từ một lần luyện đại dược thất bại trong thạch lô cổ. Dù dược tính đã hao hụt nghiêm trọng, chúng vẫn có thể tẩy luyện thân thể, cải thiện thể chất và có khả năng giúp người dùng Niết Bàn trùng sinh một lần.","detail":"Mười mảnh cổ đan trắng như ngọc được tìm thấy tại nơi dược tính tập trung trong thạch lô cổ, là tàn dư của một lần luyện đại dược thất bại. Chúng không có hoa văn nhưng mơ hồ phát ra tiếng kinh văn. Thạch Hạo giành được ba mảnh và dùng một mảnh phối hợp với Tiên Cổ pháp để tẩy luyện thân thể. Dù dược tính đã hao hụt nghiêm trọng, cổ đan vẫn có tác dụng cải thiện thể chất và tiềm năng giúp người dùng Niết Bàn trùng sinh một lần. @c1165","phanLoaiPhu":"Mảnh thuốc chủ yếu luyện thất bại","hinhDang":"Mảnh đan trắng như ngọc","dacDiem":"Mảnh đan trắng như ngọc, không có hoa văn và mơ hồ phát ra tiếng kinh văn; dược tính đã hao hụt nghiêm trọng.","chuHienThoi":"Thạch Hạo","congNang":["Cải thiện thể chất và tẩy luyện thân thể; có thể phối hợp với Tiên Cổ pháp để tiến hành tẩy luyện. @c1165","Có khả năng giúp người dùng Niết Bàn trùng sinh một lần. @c1165"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1165","denChuong":"","cachCoDuoc":"Giành được ba mảnh sau cuộc hỗn chiến","trangThai":"đã dùng một mảnh, còn hai mảnh"}],"tabs":{"tienTrinh":[{"chuong":"@c1165","loai":"đổi chủ","importance":"major","giaiDoan":"Tranh đoạt và sử dụng","text":"Thạch Hạo giành được ba mảnh cổ đan trắng và dùng một mảnh phối hợp với Tiên Cổ pháp để tẩy luyện thân thể.","anchor":"nó lại để cho người Niết Bàn trùng sinh một lần cũng không phải vấn đề lớn"}]},"capNhatToi":"@c1165","nguon":["@c1165"],"uyLuc":"Dù dược tính đã hao hụt nghiêm trọng, mảnh cổ đan vẫn có khả năng giúp người dùng Niết Bàn trùng sinh một lần. @c1165"},{"id":"hoang-kim-bao-an-cua-vuong-hi","name":"Hoàng Kim bảo ấn của Vương Hi","cn":"","category":"phap-bao","categoryLabel":"Bí bảo","phamCap":"","soHuu":["Vương Hi"],"trangThai":"Đang thuộc Vương Hi","blurb":"Bảo ấn màu hoàng kim được Vương Hi dùng để tập kích Thạch Hạo trong cuộc tranh đan.","detail":"Bảo ấn đánh thẳng vào lưng Thạch Hạo, khiến hắn khí huyết sôi trào và ho ra máu nhưng không làm tổn thương gân cốt.","hinhDang":"Một khối bảo ấn màu hoàng kim","uyLuc":"Có thể khiến Thạch Hạo ho ra máu khi đánh trúng lưng.","chuHienThoi":"Vương Hi","congNang":["Dùng lực va đập để công kích trực tiếp mục tiêu @c1165"],"chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1165","denChuong":"","cachCoDuoc":"","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1165","loai":"dùng","importance":"normal","giaiDoan":"Tập kích Thạch Hạo","text":"Vương Hi tế ra Hoàng Kim bảo ấn đánh trúng lưng Thạch Hạo và khiến hắn ho ra máu.","anchor":"cái kia là một khối Hoàng Kim bảo ấn. Rắn rắn chắc chắc đập vào trên lưng của hắn"}]},"capNhatToi":"@c1165","nguon":["@c1165"]},{"id":"than-tam-ti-chien-y-cua-yeu-nguyet","name":"Thần Tàm ti chiến y của Yêu Nguyệt","cn":"","category":"phap-bao","categoryLabel":"Chiến y","phamCap":"","soHuu":["Yêu Nguyệt Công Chúa"],"trangThai":"Bị Côn Bằng trảo xé rách phần lớn tay áo","blurb":"Chiến y bằng Thần Tàm ti của Yêu Nguyệt Công Chúa, có độ cứng cỏi vượt nhiều loại Thần Kim chiến giáp.","detail":"Trong lúc tranh giành cổ đan với Thạch Hạo, chiến y bị Côn Bằng trảo xé rách phần lớn tay áo dù chất liệu có độ cứng cỏi rất cao.","vatLieu":"Thần Tàm ti","dacDiem":"Cứng cỏi hơn nhiều loại Thần Kim chiến giáp.","chuHienThoi":"Yêu Nguyệt Công Chúa","chuSoHuu":[{"ten":"Yêu Nguyệt Công Chúa","tuChuong":"@c1165","denChuong":"","cachCoDuoc":"","trangThai":"đang giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1165","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị xé rách","text":"Côn Bằng trảo của Thạch Hạo xé rách phần lớn tay áo của Thần Tàm ti chiến y.","anchor":"loại này Thần Tàm ti cứng cỏi vô cùng, so với rất nhiều Thần Kim chiến giáp đều rắn chắc"}]},"capNhatToi":"@c1165","nguon":["@c1165"]},{"id":"than-kim-ao-giap-va-ho-tam-bao-kinh-cua-vuong-hi","name":"Thần Kim áo giáp và hộ tâm bảo kính của Vương Hi","cn":"","category":"phap-bao","categoryLabel":"Phòng ngự bảo cụ","phamCap":"","soHuu":["Vương Hi"],"trangThai":"Áo giáp nứt vỡ, hộ tâm bảo kính nổ tung","blurb":"Bộ phòng ngự bảo vệ thân thể Vương Hi trong cuộc hỗn chiến tranh cổ đan.","detail":"Một chưởng của Thạch Hạo đánh nứt Thần Kim áo giáp và khiến hộ tâm bảo kính nổ tung, sau đó Vương Hi thổ huyết bay ra.","phanLoaiPhu":"Áo giáp và hộ tâm kính","vatLieu":"Thần Kim","chuHienThoi":"Vương Hi","congNang":["Bảo vệ thân thể và vùng ngực của người mặc @c1165"],"chuSoHuu":[{"ten":"Vương Hi","tuChuong":"@c1165","denChuong":"","cachCoDuoc":"","trangThai":"hư hỏng"}],"tabs":{"tienTrinh":[{"chuong":"@c1165","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Bị Thạch Hạo phá vỡ","text":"Thạch Hạo đánh nứt Thần Kim áo giáp và phá nổ hộ tâm bảo kính của Vương Hi.","anchor":"Thần Kim áo giáp nứt vỡ, một mặt hộ tâm bảo kính càng là nổ tung"}]},"capNhatToi":"@c1165","nguon":["@c1165"]},{"id":"phoi-duoc-tien-dan-mau-vang-sam","name":"Phối dược tiên đan màu vàng sậm","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Phối dược tiên đan","soHuu":["Thạch Hạo"],"trangThai":"đã dùng","blurb":"Một loại phối dược tiên đan màu vàng sậm, trên bề mặt có hoa văn ngôi sao.","detail":"Thạch Hạo hòa phối dược thành chất lỏng trong đỉnh để hấp thu. Dược lực khiến đạo tiên khí thứ ba của hắn tiếp tục ngưng tụ và tiến gần trạng thái kết hoa.","phanLoaiPhu":"Phối dược","hinhDang":"Màu vàng sậm, bề mặt có hoa văn ngôi sao.","dacDiem":"Được hòa thành chất lỏng để hỗ trợ quá trình bồi dưỡng tiên khí.","chuHienThoi":"Thạch Hạo","congNang":["Bồi dưỡng và thúc đẩy đạo tiên khí thứ ba ngưng tụ."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1166","denChuong":"@c1166","cachCoDuoc":"","trangThai":"đã dùng"}],"tabs":{"tienTrinh":[{"chuong":"@c1166","loai":"dùng","importance":"normal","giaiDoan":"Bồi dưỡng tiên khí thứ ba","text":"Thạch Hạo hòa phối dược trong đỉnh và dùng dược lực để thúc đẩy đạo tiên khí thứ ba ngưng tụ.","anchor":"một loại nào đó tiên đan phối hợp dược, hiện màu vàng sậm, mặt trên có ngôi sao hoa văn các loại","phamCap":"Phối dược tiên đan"}]},"capNhatToi":"@c1166","nguon":["@c1166"]},{"id":"that-thai-tien-kim-tien","name":"Thất Thải Tiên Kim tiễn","cn":"","aliases":["Bảy màu tiên kim tiễn","Mũi tên bảy màu tiên kim"],"category":"phap-bao","categoryLabel":"Pháp bảo","phanLoaiPhu":"Tuyệt thế bí bảo dạng mũi tên","phamCap":"Tuyệt thế bí bảo","soHuu":["Phượng Vũ","Kim Vân"],"trangThai":"Đang do Kim Vân nắm giữ","blurb":"Thất Thải Tiên Kim tiễn là pháp khí dạng mũi tên được đúc từ bảy màu tiên kim, vốn do thư viện của Phượng Vũ tìm kiếm vật liệu và chuẩn bị rèn cho nàng. Sau khi đánh Phượng Vũ bị thương, Kim Vân đoạt lấy, luyện hóa rồi dùng bảo vật tập kích Thạch Hạo, nhưng bị hắn né tránh bằng tàn ảnh.","detail":"Bảo vật có hình dạng mũi tên, phát hào quang bảy màu và tiên quang mờ mịt. Nó vốn được thư viện của Phượng Vũ chuẩn bị cho nàng từ tiên kim, đồng thời có khả năng tiếp tục lột xác theo sự trưởng thành của chủ nhân. Vì giá trị của vật liệu tiên kim, Kim Vân chủ động đánh Phượng Vũ bị thương để chiếm đoạt bảo vật @c1169; sau khi luyện hóa, hắn dùng mũi tên bất ngờ tập kích Thạch Hạo, song đối phương tạo tàn ảnh và né được đòn @c1173.","hinhDang":"Mũi tên","vatLieu":"Bảy màu tiên kim","nguonGoc":"Được thư viện của Phượng Vũ tìm tiên kim và chuẩn bị rèn cho nàng.","dacDiem":"Được đúc từ bảy màu tiên kim, có hình dạng mũi tên, phát hào quang bảy màu cùng tiên quang mờ mịt.","chuHienThoi":"Kim Vân","congNang":["Dùng làm pháp khí dạng mũi tên.","Có thể xuyên sát cả hình lẫn thần.","Có thể tiếp tục lột xác theo sự trưởng thành của chủ nhân.","Sau khi được luyện hóa, có thể dùng để bất ngờ tập kích mục tiêu @c1173."],"chuSoHuu":[{"ten":"Phượng Vũ","tuChuong":"@c1169","denChuong":"@c1169","cachCoDuoc":"Được thư viện chuẩn bị rèn để giao sử dụng","trangThai":"bị đoạt"},{"ten":"Kim Vân","tuChuong":"@c1169","denChuong":"","cachCoDuoc":"Cướp từ Phượng Vũ rồi luyện hóa.","trangThai":"Đang nắm giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1169","loai":"đổi chủ","importance":"major","giaiDoan":"Kim Vân đoạt bảo","phamCap":"Tuyệt thế bí bảo","text":"Kim Vân đánh Phượng Vũ bị thương và đoạt mũi tên được đúc từ bảy màu tiên kim.","anchor":"Lấy bảy màu tiên kim đúc thành tuyệt thế bí bảo, xác thực đáng giá ta ra tay"},{"chuong":"@c1173","loai":"dùng","importance":"normal","giaiDoan":"Đánh lén Thạch Hạo","text":"Kim Vân dùng mũi tên đã cướp và luyện hóa để bất ngờ tập kích Thạch Hạo, nhưng hắn tạo tàn ảnh né được đòn tuyệt sát.","anchor":"đó là bảy màu tiên kim đúc thành mũi tên"}]},"capNhatToi":"@c1169","nguon":["@c1169","@c1173"],"uyLuc":"Có khả năng xuyên sát cả hình lẫn thần; khi được Kim Vân dùng tập kích Thạch Hạo, đòn đánh đã bị hắn tạo tàn ảnh né tránh @c1173."},{"id":"bay-mau-tien-kim","name":"Bảy màu tiên kim","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Tiên kim","soHuu":[],"trangThai":"Đã được dùng đúc mũi tên","blurb":"Loại tiên kim quý được dùng để đúc mũi tên vốn thuộc về Phượng Vũ.","detail":"Vật liệu tạo nên một mũi tên lóng lánh cầu vồng và có giá trị đủ lớn để Kim Vân chủ động tranh đoạt.","dacDiem":"Phát hào quang bảy màu.","congNang":["Dùng làm vật liệu đúc tuyệt thế bí bảo."],"tabs":{"tienTrinh":[{"chuong":"@c1169","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ diện qua mũi tên","phamCap":"Tiên kim","text":"Bảy màu tiên kim được xác nhận là vật liệu tạo nên mũi tên lóng lánh cầu vồng bị Kim Vân đoạt.","anchor":"đó là một mũi tên, lóng lánh cầu vồng, vừa nhìn liền biết là tuyệt thế bảo vật"}]},"capNhatToi":"@c1169","nguon":["@c1169"]},{"id":"phuc-thien-an-hang-nhai","name":"Phúc Thiên Ấn hàng nhái","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo ấn","phanLoaiPhu":"Hàng nhái của Phúc Thiên Ấn","phamCap":"Bí bảo","soHuu":["Thạch Hạo"],"trangThai":"Đã bị Thạch Hạo luyện hóa","blurb":"Phúc Thiên Ấn hàng nhái là bảo ấn màu bích lục từng thuộc Kim Vân, có thể phóng lớn như núi để trấn áp mục tiêu. Sau khi không thể trấn áp Thạch Hạo, nó bị thần liên trật tự trói buộc, ép thu nhỏ, luyện hóa và đổi chủ @c1172.","detail":"Đây là hàng nhái mô phỏng Phúc Thiên Ấn, ban đầu do Kim Vân sử dụng. Khi được phóng lớn như núi, bảo ấn có thể đè ép mục tiêu, làm sụp hư không xung quanh và nghiền vỡ núi non. Trong trận đối đầu với Thạch Hạo, nó không thể trấn áp được đối phương, trái lại bị thần liên trật tự trói buộc, ép trở về hình thái tiểu ấn màu bích lục, sau đó bị luyện hóa, nuốt vào cơ thể và đổi chủ @c1172.","hinhDang":"Bảo ấn màu xanh; khi thu nhỏ chỉ cao hơn một tấc.","nguonGoc":"Hàng nhái mô phỏng Phúc Thiên Ấn.","uyLuc":"Khi phóng lớn, bảo ấn có thể ép sụp hư không và nghiền vỡ núi non.","dacDiem":"Là hàng nhái mô phỏng Phúc Thiên Ấn; có thể biến đổi giữa hình thái lớn như núi và một tiểu ấn màu bích lục.","chuHienThoi":"Thạch Hạo","congNang":["Phóng lớn như núi để trấn áp mục tiêu.","Ép sụp hư không và nghiền vỡ núi non.","Có thể thu nhỏ thành một tiểu ấn màu bích lục."],"chuSoHuu":[{"ten":"Kim Vân","tuChuong":"@c1172","denChuong":"@c1172","cachCoDuoc":"","trangThai":"đã mất"},{"ten":"Thạch Hạo","tuChuong":"@c1172","denChuong":"","cachCoDuoc":"Đoạt trong giao chiến rồi dùng cốt văn luyện hóa.","trangThai":"hiện tại"}],"capNhatToi":"@c1172","tabs":{"tienTrinh":[{"chuong":"@c1172","loai":"đổi chủ","importance":"major","giaiDoan":"Bị đoạt và luyện hóa","phamCap":"Bí bảo","text":"Phúc Thiên Ấn hàng nhái không thể trấn áp Thạch Hạo, bị thần liên trật tự trói buộc rồi thu nhỏ và đổi chủ.","anchor":"cuối cùng hóa thành cao hơn một tấc bích lục tiểu ấn, bị hắn một cái nắm ở trong tay"}]},"nguon":["@c1172"]},{"id":"ngoc-thach-kinh-thu","name":"Ngọc thạch kinh thư","cn":"","aliases":[],"category":"khac","categoryLabel":"Kinh thư","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang do Thạch Hạo nắm giữ","blurb":"Kinh thư bằng ngọc thạch Thạch Hạo lấy được tại Tiên Cổ di địa ở ba nghìn Đạo Châu.","detail":"Vật phẩm ghi chép Tiên Cổ pháp để tham ngộ. Thạch Hạo dự định sau khi vào Giới phần tìm tiên chủng sẽ nghiên cứu nội dung kinh thư.","phanLoaiPhu":"Kinh thư tu hành","nguonGoc":"Tiên Cổ di địa tại ba nghìn Đạo Châu","chuHienThoi":"Thạch Hạo","dacDiem":"Ghi chép truyền thừa liên quan Tiên Cổ pháp.","congNang":["Ghi chép Tiên Cổ pháp để người nắm giữ tham ngộ."],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1178","denChuong":"","cachCoDuoc":"Lấy được tại Tiên Cổ di địa ở ba nghìn Đạo Châu.","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1178","loai":"nhắc tới","importance":"normal","giaiDoan":"Chuẩn bị tham ngộ","text":"Thạch Hạo dự định mang ngọc thạch kinh thư vào kế hoạch tu hành sau khi tới Giới phần tìm tiên chủng.","anchor":"bởi vì trên người hắn có ngọc thạch kinh thư, là năm đó tại 3000 Đạo Châu Tiên Cổ di địa trung được đến","phamCap":"Không rõ"}]},"capNhatToi":"@c1178","nguon":["@c1178"]},{"id":"hoan-my-vu-tru-hat-giong","name":"Hoàn mỹ vũ trụ hạt giống","cn":"","category":"khac","categoryLabel":"Tiên chủng","phamCap":"Tiên chủng hoàn mỹ","soHuu":[],"trangThai":"Được truyền là từng xuất hiện tại Giới phần","blurb":"Một loại tiên chủng hoàn mỹ được nhắc đến trong truyền thuyết về Giới phần.","detail":"Bạch Kỳ Lân ấu thú cho biết từng có sinh linh phát hiện hoàn mỹ vũ trụ hạt giống tại Giới phần và gọi đây là tiên chủng mạnh nhất.","phanLoaiPhu":"Tiên chủng","nguonGoc":"Từng được phát hiện tại Giới phần","uyLuc":"Được mô tả là loại tiên chủng mạnh nhất.","dacDiem":"Mang tính chất của một vũ trụ hoàn mỹ.","capNhatToi":"@c1180","congNang":["Có thể được người tu Cổ pháp lựa chọn làm tiên chủng cho con đường tu hành."],"chuSoHuu":[],"tabs":{"tienTrinh":[{"chuong":"@c1180","loai":"xuất hiện","importance":"normal","giaiDoan":"Truyền thuyết tại Giới phần","text":"Bạch Kỳ Lân ấu thú tiết lộ rằng từng có sinh linh phát hiện hoàn mỹ vũ trụ hạt giống tại Giới phần.","anchor":"nghe nói có sinh linh tại đâu đó phát hiện qua hoàn mỹ vũ trụ hạt giống, là cường đại nhất tiên chủng","phamCap":"Tiên chủng hoàn mỹ"}]},"nguon":["@c1180"]},{"id":"te-dan-truyen-chieu-tien-co","name":"Tế đàn truyền chiếu Tiên Cổ","cn":"","aliases":[],"category":"khac","categoryLabel":"Tế đàn","phamCap":"Di vật Tiên Cổ","soHuu":["Sinh linh dị vực"],"trangThai":"Đang hoạt động","blurb":"Tế đàn cực lớn và rách nát do sinh linh dị vực để lại từ kỷ nguyên Tiên Cổ. Nó chiếu hư ảnh Hoàng Kim Tam Đầu Vương và cưỡng ép mở một cánh cửa nối liền hai thế giới.","detail":"Bề mặt tế đàn phủ văn lạc phức tạp và có thể phát ra vô số ký hiệu. Những ký hiệu hội tụ thành môn hộ thông với dị vực, qua đó một sứ giả mặc Hắc Ám Tiên Kim dùng chân thân vượt sang cửu thiên thập địa; khả năng đưa đại quân vượt qua chưa được xác nhận.","phanLoaiPhu":"Tế đàn truyền chiếu và vượt giới","hinhDang":"Tế đàn cực lớn, rách nát và phủ văn lạc phức tạp","nguonGoc":"Do sinh linh dị vực để lại khi rút đi từ kỷ nguyên Tiên Cổ","uyLuc":"Có thể cưỡng ép kết nối hai thế giới và đưa một cường giả chân thân vượt qua.","dacDiem":"Phát ra vô số ký hiệu rồi ngưng tụ thành một cánh cửa thông với dị vực.","chuHienThoi":"Sinh linh dị vực","capNhatToi":"@c1182","congNang":["Chiếu hư ảnh Hoàng Kim Tam Đầu Vương sang cửu thiên thập địa.","Ngưng tụ cánh cửa cưỡng ép nối liền cửu thiên thập địa với dị vực.","Cho phép một sứ giả dùng chân thân vượt qua cửa giới."],"chuSoHuu":[{"ten":"Sinh linh dị vực","tuChuong":"@c1182","denChuong":"","cachCoDuoc":"Di vật được lưu lại từ kỷ nguyên Tiên Cổ","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1182","loai":"dùng","importance":"normal","giaiDoan":"Mở cửa nối hai giới","text":"Tế đàn chiếu hư ảnh Hoàng Kim Tam Đầu Vương, sau đó phát ra vô số ký hiệu và ngưng tụ thành cánh cửa để sứ giả dị vực vượt giới.","anchor":"Tế đàn mông lung, phát ra hằng hà ký hiệu, cuối cùng ngưng tụ thành một cánh cửa","phamCap":"Di vật Tiên Cổ"}]},"nguon":["@c1182"]},{"id":"hac-am-tien-kim-chien-y","name":"Hắc ám tiên kim chiến y","cn":"","aliases":["Hắc Ám Tiên Kim áo giáp","Hắc ám tiên kim giáp trụ","Hắc ám tiên giáp vàng trụ","Hắc sắc tiên kim chiến y"],"category":"phap-bao","categoryLabel":"Áo giáp","phamCap":"Không rõ","soHuu":["Độc Cô Vân"],"trangThai":"Đang được sử dụng","blurb":"Chiến y luyện từ Hắc Ám Tiên Kim, bao phủ kín sứ giả vượt giới. Nó che giấu khí tức, phát sáng khi dò xét quy tắc và bảo vệ người mặc trước lực bài xích của cửu thiên thập địa.","detail":"Chiến y che kín cả diện mạo lẫn thân thể nên người ngoài không thể nhận biết giới tính, khí tức hay thực lực của người mặc. Các ký hiệu đại đạo trên giáp sáng lên trong quá trình dò xét quy tắc, sau đó chiến y phát ô quang như Mặc Ngọc để thủ hộ toàn thân.","phanLoaiPhu":"Chiến y hộ thân và che giấu khí tức","hinhDang":"Bao phủ kín toàn thân và khuôn mặt người mặc","vatLieu":"Hắc Ám Tiên Kim","uyLuc":"Có thể chống đỡ lực bài xích của cửu thiên thập địa đối với sinh linh vượt giới.","dacDiem":"Phát ô quang như Mặc Ngọc và hiện các ký hiệu đại đạo khi dò xét quy tắc thiên địa.","chuHienThoi":"Độc Cô Vân","capNhatToi":"@c1182","congNang":["Che kín diện mạo, ngăn cách khí tức và che giấu thực lực của người mặc.","Dò xét sự mạnh yếu của quy tắc thiên địa thông qua các ký hiệu đại đạo.","Phát ô quang bảo vệ toàn thân trước lực bài xích của cửu thiên thập địa."],"chuSoHuu":[{"ten":"Độc Cô Vân","tuChuong":"@c1182","denChuong":"","cachCoDuoc":"Mặc khi làm sứ giả vượt qua cửa giới","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1182","loai":"dùng","importance":"normal","giaiDoan":"Bảo vệ sứ giả vượt giới","text":"Chiến y che giấu khí tức của Độc Cô Vân, dò xét quy tắc thiên địa và phát ô quang bảo vệ người mặc trước lực bài xích của thế giới.","anchor":"Rất nhanh, nó áo giáp tựu rung động bắt đầu chuyển động, phát ra ô quang, thủ hộ toàn thân của nó.","phamCap":"Không rõ"}]},"nguon":["@c1182"]},{"id":"huyet-sac-chien-mau","name":"Huyết sắc chiến mâu","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Các trưởng lão Thiên Thần Thư Viện"],"trangThai":"Đang được sử dụng","blurb":"Chiến mâu đỏ thẫm như mã não được một trưởng lão Thiên Thần Thư Viện lấy ra khi Hoàng Kim Tam Đầu Vương hiện hình.","detail":"Binh khí sắc bén, mang sát khí và được dùng để đề phòng cuộc xâm nhập từ dị vực.","chuHienThoi":"Các trưởng lão Thiên Thần Thư Viện","capNhatToi":"@c1182","nguon":["@c1182"]},{"id":"mau-vang-hoa-den-cua-nguoi-bao-ve","name":"Máu vàng hóa đen của người bảo vệ","cn":"","aliases":[],"category":"khac","categoryLabel":"Huyết mạch","phamCap":"Không rõ","soHuu":["Độc Cô Vân"],"trangThai":"Bị lấy mẫu và luyện hóa","blurb":"Huyết dịch của hậu nhân người bảo vệ vốn vàng óng, giàu thần tính, nhưng một tia vẫn tồn tại sau quá trình luyện hóa cực hạn rồi chuyển thành màu đen như mực. Khi hóa đen, tia máu mất thần tính, bộc lộ lệ khí và sức mạnh khiến người chứng kiến kinh sợ.","detail":"Phần lớn máu vàng của hậu nhân người bảo vệ bị luyện đến khô cạn thành tro, song một tia không bị tiêu diệt mà chuyển từ vàng óng sang đen kịt. Tia máu sau biến đổi không còn thần tính, thay vào đó phát ra lệ khí cùng sức mạnh đáng sợ. Tam Đầu Vương từng lấy hiện tượng này làm căn cứ công kích nguồn gốc của người bảo vệ, nhưng cách giải thích ấy không được các trưởng lão công nhận. @c1184","phanLoaiPhu":"Huyết dịch huyết mạch","hinhDang":"Các giọt máu vàng, trong đó một tia chuyển thành đen như mực","nguonGoc":"Hậu nhân người bảo vệ","uyLuc":"Một tia huyết dịch vẫn tồn tại sau quá trình luyện hóa cực hạn và phát ra khí tức khiến người chứng kiến kinh sợ. @c1184","dacDiem":"Từ trạng thái vàng óng, giàu thần tính chuyển thành đen kịt như mực, mất thần tính và đầy lệ khí khi bị áp chế. @c1184","chuHienThoi":"Độc Cô Vân","congNang":["Thể hiện sinh lực ngoan cường khi vẫn tồn tại sau quá trình luyện hóa cực hạn. @c1184","Sau khi chuyển thành màu đen, huyết dịch mất thần tính và bộc lộ lệ khí cùng sức mạnh đáng sợ. @c1184"],"chuSoHuu":[{"ten":"Độc Cô Vân","tuChuong":"@c1184","denChuong":"","cachCoDuoc":"Huyết dịch bẩm sinh của huyết mạch người bảo vệ","trangThai":"Một phần bị Tam Đầu Vương lấy ra luyện hóa"}],"capNhatToi":"@c1184","tabs":{"tienTrinh":[{"chuong":"@c1184","loai":"khai phong","importance":"major","giaiDoan":"Máu vàng chuyển đen","text":"Một tia máu vàng không bị tiêu diệt trong quá trình luyện hóa mà chuyển thành màu đen như mực.","anchor":"Cái kia một tia tơ máu hóa thành màu đen, không lại vàng óng ánh, mà là đen kịt như mực","phamCap":"Không rõ"}]},"nguon":["@c1184"]},{"id":"dong-thau-thien-mau","name":"Đồng thau thiên mâu","cn":"","category":"phap-bao","categoryLabel":"Vũ khí","phamCap":"Không rõ","soHuu":["Thánh Viện sứ giả"],"trangThai":"Nguyên vẹn","blurb":"Cây thiên mâu bằng đồng thau được Thánh Viện sứ giả mang tới Thiên Thần Thư Viện.","detail":"Thánh Viện sứ giả vác cây thiên mâu này trên vai khi xuất hiện tại sơn môn. Chương này chưa cho thấy hắn sử dụng nó trong giao chiến.","phanLoaiPhu":"Thiên mâu","hinhDang":"Một cây thiên mâu được vác trên vai","vatLieu":"Đồng thau","chuHienThoi":"Thánh Viện sứ giả","chuSoHuu":[{"ten":"Thánh Viện sứ giả","tuChuong":"@c1187","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1187","nguon":["@c1187"]},{"id":"chien-ham-bac","name":"Chiến hạm bạc","cn":"","aliases":[],"category":"khac","categoryLabel":"Phương tiện","phamCap":"","soHuu":["Thiên Thần Thư Viện"],"trangThai":"Đang sử dụng","blurb":"Chiến hạm màu bạc dài mấy vạn trượng, được Thiên Thần Thư Viện dùng để đưa đoàn kỳ tài tới Giới Phần.","detail":"Chiến hạm chở Nhị Trưởng Lão, Thạch Hạo, Độc Cô Vân cùng những kỳ tài khác rời Thiên Thần Thư Viện và vượt qua tế đàn tới Giới Phần.","phanLoaiPhu":"Chiến hạm","hinhDang":"Chiến hạm màu bạc dài mấy vạn trượng","dacDiem":"Có kích thước khổng lồ và được dùng trong hành trình tới Giới Phần.","congNang":["Chuyên chở đoàn kỳ tài vượt qua tế đàn tới Giới Phần."],"chuHienThoi":"Thiên Thần Thư Viện","chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1188","denChuong":"","cachCoDuoc":"Thuộc phương tiện do thư viện điều động","trangThai":"Đang sử dụng"}],"dinhDanh":"goc","capNhatToi":"@c1188","tabs":{"tienTrinh":[{"chuong":"@c1188","loai":"xuất hiện","importance":"normal","giaiDoan":"Đưa đoàn kỳ tài tới Giới Phần","text":"Chiến hạm bạc chở đoàn Thiên Thần Thư Viện rời đi qua tế đàn để tới Giới Phần.","anchor":"Một chiếc mấy vạn trượng trường chiến hạm màu bạc nhằm phía bầu trời"}]},"nguon":["@c1188"]},{"id":"hat-giong-vu-tru-khong-tron-ven","name":"Hạt giống vũ trụ không trọn vẹn","cn":"","category":"khac","categoryLabel":"Vũ trụ chủng","phamCap":"Chí bảo nguy hiểm","soHuu":[],"trangThai":"Tàn khuyết, không ổn định và nhiễm ma tính","blurb":"Hạt giống vũ trụ không trọn vẹn là một vũ trụ chủng tàn khuyết, hiện thành dòng cát trắng có thể diễn hóa thiên địa và bắn nổ đại tinh. Từng bị một cường giả hàng phục để làm binh khí phong ma, nó đã nhiễm ma tính, không còn khả năng trưởng thành ổn định và có nguy cơ sụp nổ, phản phệ người nắm giữ.","detail":"Dị vật này xuất hiện dưới dạng một dòng cát trắng rộng khoảng mười trượng, được xác định là hạt giống vũ trụ đã tàn khuyết. Mỗi hạt cát nặng hơn một đại tinh, bên trong có thể diễn hóa cảnh tượng thiên địa, đồng thời được bắn ra để phá hủy các ngôi sao. Do lực lượng dùng cho quá trình trưởng thành đã tiết ra ngoài, nó không còn thích hợp để dung hợp tu luyện. Trong quá khứ, một cường giả từng hàng phục và dùng nó làm binh khí phong ấn, luyện hóa một nhân vật khó lường; huyết nhục của kẻ bị phong ấn bị nghiền cùng cát, khiến vũ trụ chủng nhiễm ma tính và mang nguy cơ sụp đổ, phản phệ chủ nhân. @c1189","phanLoaiPhu":"Vũ trụ chủng tàn khuyết","hinhDang":"Dòng cát trắng rộng khoảng mười trượng","nguonGoc":"Từng bị một cường giả hàng phục và dùng làm binh khí phong ma","uyLuc":"Mỗi hạt cát đều có thể đánh nổ một đại tinh; khi xuất hiện, dòng cát trắng đã bắn nổ nhiều đại tinh. @c1189","dacDiem":"Mang hình thái dòng cát trắng rộng khoảng mười trượng; mỗi hạt cát nặng hơn đại tinh. Vì đã tàn khuyết và nhiễm ma tính, nó không còn khả năng trưởng thành ổn định, không thích hợp để dung hợp tu luyện, đồng thời có thể sụp nổ và phản phệ người nắm giữ.","chuHienThoi":"Không rõ","congNang":["Diễn hóa cảnh tượng thiên địa bên trong từng hạt cát. @c1189","Dùng những hạt cát nặng hơn đại tinh để bắn phá, khiến các ngôi sao nổ tung. @c1189","Làm vật dẫn để phong ấn và luyện hóa cường giả. @c1189"],"capNhatToi":"@c1189","tabs":{"tienTrinh":[{"chuong":"@c1189","loai":"xuất hiện","importance":"major","giaiDoan":"Lộ bản chất vũ trụ chủng","text":"Dòng cát trắng bắn nổ nhiều đại tinh và được xác định là một hạt giống vũ trụ đã tàn khuyết. Lai lịch phong ma cùng nguy cơ sụp đổ, nhiễm ma tính và phản phệ chủ nhân của vật này cũng được hé lộ.","anchor":"Một hạt sa mà thôi, so với chân chính đại tinh mà còn nặng hơn","phamCap":"Chí bảo nguy hiểm"}]},"nguon":["@c1189"]},{"id":"co-thu-ket-tinh-cau","name":"Cổ thụ kết tinh cầu","cn":"","category":"khac","categoryLabel":"Dị vật cổ thụ","phamCap":"Không rõ","soHuu":[],"trangThai":"Khô héo","blurb":"Cổ thụ khổng lồ nằm sâu trong Giới Phần, có vô số đại tinh treo trên cành như quả. Thân cây mang nhiều hố đen không thể khép lại và được xác nhận không phải Thế Giới Thụ.","detail":"Cây lớn đến mức người vận dụng Thiên Nhãn thông cũng chỉ thấy đường nét mơ hồ. Trên các cành là vô số đại tinh giống như trái cây, còn thân cây khô héo mang những hố đen không thể khép kín.","phanLoaiPhu":"Dị vật cổ thụ","hinhDang":"Cổ thụ khô héo khổng lồ với vô số đại tinh trên cành","dacDiem":"Thân cây có nhiều hố đen không thể khép lại và không phải Thế Giới Thụ.","congNang":[],"capNhatToi":"@c1189","tabs":{"tienTrinh":[{"chuong":"@c1189","loai":"xuất hiện","importance":"normal","giaiDoan":"Được phát hiện trong Giới Phần","text":"Đoàn chiến hạm phát hiện một cổ thụ khổng lồ có vô số đại tinh treo trên cành như quả, nhưng các trưởng lão xác nhận nó không phải Thế Giới Thụ.","anchor":"Nó cành trên, kết đếm không hết đại tinh, như là một viên lại một viên trái cây","phamCap":"Không rõ"}]},"nguon":["@c1189"]},{"id":"thuc-vat-xanh-nuot-sao","name":"Thực vật xanh nuốt sao","cn":"","category":"khac","categoryLabel":"Dị thực vật","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang nuốt chửng các ngôi sao","blurb":"Dị thực vật xanh biếc trong Giới Phần, có hình thái vừa giống thân cây vừa mang nhiều lá cỏ. Những phiến lá của nó từng bước xâm chiếm và nuốt chửng các ngôi sao.","detail":"Thực vật có phần thân xanh biếc giống cây nhưng đồng thời mọc ra nhiều lá cỏ. Khi chiến hạm phát hiện, các phiến lá của nó đang bao phủ và nuốt dần những ngôi sao gần đó.","phanLoaiPhu":"Dị thực vật","hinhDang":"Thân xanh biếc giống cây và mọc nhiều lá cỏ","uyLuc":"Có thể dùng các phiến lá xâm chiếm và nuốt chửng ngôi sao.","dacDiem":"Mang đồng thời đặc điểm của thân cây và thảo diệp.","congNang":["Dùng phiến lá từng bước xâm chiếm và nuốt chửng ngôi sao."],"capNhatToi":"@c1189","tabs":{"tienTrinh":[{"chuong":"@c1189","loai":"xuất hiện","importance":"normal","giaiDoan":"Lộ diện khi nuốt sao","text":"Đoàn người phát hiện một thực vật xanh biếc đang dùng các phiến lá xâm chiếm và nuốt chửng những ngôi sao.","anchor":"nó phiến lá ở từng bước xâm chiếm ngôi sao, không ngừng nuốt chửng mà xuống","phamCap":"Không rõ"}]},"nguon":["@c1189"]},{"id":"huyet-sac-co-thuyen","name":"Huyết sắc cổ thuyền","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Chiến thuyền cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"Tàn tạ nhưng chưa mục nát","blurb":"Chiến thuyền cổ chở chiến linh, trôi ra từ phế tích tinh cầu trong Giới Phần. Nó tỏa khói xám ăn mòn thần lực và bám đuổi mục tiêu đã khóa.","detail":"Huyết sắc cổ thuyền có vẻ ngoài tàn tạ nhưng vẫn hoạt động, mang theo nhiều chiến linh và phát ra tiếng gào tác động trực tiếp tới linh hồn. Khi khóa chặt chiến hạm màu bạc, nó truy đuổi không ngừng và chuẩn bị phóng các bóng người ra tập kích.","phanLoaiPhu":"Chiến thuyền cổ","hinhDang":"Một chiếc thuyền cổ màu máu, tàn tạ nhưng chưa mục nát","uyLuc":"Khói xám của thuyền có thể xuyên qua phòng ngự và ăn mòn thần lực, còn tiếng gào từ bên trong tác động thẳng vào linh hồn.","dacDiem":"Có thể khóa mục tiêu, truy đuổi không ngừng và chở theo nhiều chiến linh.","chuHienThoi":"","congNang":["Khóa chặt mục tiêu và truy đuổi không chết không thôi.","Tỏa khói xám xâm chiếm và ăn mòn thần lực.","Chở chiến linh lao ra tập kích đối phương."],"chuSoHuu":[],"dinhDanh":"goc","capNhatToi":"@c1190","tabs":{"tienTrinh":[{"chuong":"@c1190","loai":"xuất hiện","importance":"normal","giaiDoan":"Khóa chặt chiến hạm","text":"Huyết sắc cổ thuyền trôi ra từ phế tích tinh cầu, tỏa khói xám ăn mòn thần lực và khóa chiến hạm màu bạc. Cuối chương, nhiều bóng người trên thuyền bắt đầu lao ra tập kích.","anchor":"một chiếc huyết sắc cổ thuyền xuất hiện, từ tinh cầu phế tích bên trong trôi nổi mà đến","phamCap":"Không rõ"}]},"nguon":["@c1190"]},{"id":"doan-canh-the-gioi-thu","name":"Đoạn cành Thế Giới Thụ","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Linh căn","phamCap":"Không rõ","soHuu":[],"trangThai":"Khô héo, chỉ còn hài cốt","blurb":"Một đoạn cành bị cắt khỏi Thế Giới Thụ và từng được nuôi bằng lượng lớn tinh hoa trời đất. Kế hoạch bồi dưỡng nó thành Ma Thụ cuối cùng thất bại.","detail":"Đoạn cành từng được bồi dưỡng để trở thành Ma Thụ có khả năng điều động nhật nguyệt ngân hà và hút sức mạnh bầu trời. Cây mất hết tinh khí thần, còn người bồi dưỡng cũng chết và hóa vào trong thân cây.","phanLoaiPhu":"Linh căn","nguonGoc":"Được cắt ra từ Thế Giới Thụ","dacDiem":"Từng kết nhiều trái cây mang hình dạng ngôi sao nhưng cuối cùng đã khô héo.","chuHienThoi":"","congNang":["Từng được bồi dưỡng với mục đích điều động nhật nguyệt ngân hà và hấp thu sức mạnh bầu trời."],"chuSoHuu":[],"dinhDanh":"goc","capNhatToi":"@c1190","tabs":{"tienTrinh":[]},"nguon":["@c1190"]},{"id":"chien-ham-mau-bac","name":"Chiến hạm màu bạc","cn":"","aliases":["Ngân sắc chiến hạm"],"category":"phap-bao","categoryLabel":"Chiến thuyền","phamCap":"Chiến hạm đỉnh cấp","soHuu":[],"trangThai":"Bị chiến linh xuyên thủng phòng tuyến","blurb":"Chiến hạm màu bạc chở đoàn người của Thiên Thần Thư Viện qua khu cổ địa. Màn sáng phòng hộ của chiến hạm bị phá khi các chiến linh nuốt và luyện hóa thần lực.","detail":"Chiến hạm có màn sáng phù văn dùng làm phòng tuyến bảo vệ. Hàng chục đến hơn trăm chiến linh đã nuốt thần lực, xuyên qua màn sáng và tràn lên boong, gây thương vong cho các học sinh.","phanLoaiPhu":"Chiến thuyền","hinhDang":"Chiến hạm màu bạc","uyLuc":"Màn sáng phù văn có khả năng phòng hộ nhưng không ngăn được chiến linh nuốt thần lực.","dacDiem":"Phòng tuyến bị xuyên thủng trong cuộc tập kích của chiến linh.","chuHienThoi":"Thiên Thần Thư Viện","capNhatToi":"@c1191","congNang":["Dựng màn sáng phù văn phòng hộ cho người trên chiến hạm."],"chuSoHuu":[{"ten":"Thiên Thần Thư Viện","tuChuong":"@c1191","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1191","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Phòng tuyến bị công phá","text":"Chiến linh nuốt thần lực, xuyên thủng màn sáng phòng hộ và tràn lên Chiến hạm màu bạc.","anchor":"Chiến hạm màu bạc bị công phá, nhân vì chúng nó nuốt thần lực","phamCap":"Chiến hạm đỉnh cấp"}]},"nguon":["@c1191"]},{"id":"hon-luc-hat-giong","name":"Hồn lực hạt giống","cn":"","aliases":[],"category":"khac","categoryLabel":"Hạt giống tu cổ pháp","phanLoaiPhu":"Hạt giống hồn lực","phamCap":"Hoàn mỹ, vô giá","soHuu":["Thạch Hạo"],"trangThai":"Đã được Thạch Hạo thu vào duy nhất động thiên","blurb":"Hồn lực hạt giống rơi ra từ huyết sắc cổ thuyền sau khi con thuyền bị Nhị Trưởng Lão bổ vỡ. Hồn lực mạnh mẽ của nó thu hút toàn bộ chiến linh gần đó, châm ngòi cuộc tranh đoạt giữa chiến linh và học sinh Thiên Thần Thư Viện.","detail":"Hồn lực hạt giống xuất hiện khi huyết sắc cổ thuyền bị Nhị Trưởng Lão bổ vỡ và được các trưởng lão đánh giá là hạt giống hoàn mỹ, vô giá. Nó khiến các chiến linh từ bỏ giao chiến để lao tới dung hợp. Sau khi vượt qua sự ngăn cản của Vương Hi, Lục Đà và Thập Quan Vương, Thạch Hạo dùng duy nhất động thiên cầm cố rồi kéo hạt giống vào bên trong. @c1192","hinhDang":"Một viên hạt giống phát sáng","nguonGoc":"Rơi ra từ huyết sắc cổ thuyền khi con thuyền bị Nhị Trưởng Lão bổ vỡ.","uyLuc":"Tỏa ra hồn lực mạnh đến mức thu hút toàn bộ chiến linh gần đó.","dacDiem":"Là hạt giống hoàn mỹ và vô giá theo đánh giá của các trưởng lão.","chuHienThoi":"Thạch Hạo","congNang":["Cung cấp hồn lực.","Có thể dung hợp với chiến linh. @c1192"],"chuSoHuu":[{"ten":"Thạch Hạo","tuChuong":"@c1192","denChuong":"","cachCoDuoc":"Dùng duy nhất động thiên cầm cố và thu vào bên trong.","trangThai":"Đang sở hữu"}],"capNhatToi":"@c1192","tabs":{"tienTrinh":[{"chuong":"@c1192","loai":"đổi chủ","importance":"major","giaiDoan":"Xuất thế và được thu giữ","text":"Hồn lực hạt giống rơi khỏi huyết sắc cổ thuyền, gây ra cuộc tranh đoạt giữa chiến linh và học sinh Thiên Thần Thư Viện. Cuối cùng Thạch Hạo dùng duy nhất động thiên cầm cố và thu lấy nó.","anchor":"ngoài ra còn có một viên phát sáng hạt giống, thả ra kinh người hồn lực","phamCap":"Hoàn mỹ, vô giá"}]},"nguon":["@c1192"]},{"id":"chuan-the-gioi-thu","name":"Chuẩn Thế Giới Thụ","cn":"","aliases":["Hoàng Kim Cổ Thụ"],"category":"khac","categoryLabel":"Thần thụ","phamCap":"Chuẩn Thế Giới Thụ","soHuu":[],"trangThai":"Đang tiến hóa","blurb":"Cổ thụ vàng khổng lồ đang tiến hóa thành Thế Giới Thụ. Nó đi qua các Cổ giới tan vỡ để hấp thu dấu ấn rồi cắm rễ tại Ngũ Hành chi địa.","detail":"Chuẩn Thế Giới Thụ có tán cây khổng lồ, lá nâng đỡ nhật nguyệt tinh thần và sức mạnh đủ tiêu diệt những người tùy tiện tiếp cận. Cây thường tiến vào Giới Phần để hấp thu dấu ấn của các Cổ giới tan vỡ, sau đó cắm rễ tại Ngũ Hành chi địa nhằm thu lấy Ngũ hành mẫu khí.","phanLoaiPhu":"Thần thụ","hinhDang":"Cổ thụ vàng khổng lồ với tán cây nâng đỡ nhật nguyệt tinh thần","nguonGoc":"Từng được Thạch Hạo biết đến như Thái Dương Cổ Thụ","uyLuc":"Có thể giam cầm và khiến những người tiếp cận hình thần câu diệt.","dacDiem":"Đang tiến hóa thành Thế Giới Thụ và chủ động tìm đến những vùng có dấu ấn Cổ giới cùng bản nguyên mạnh.","capNhatToi":"@c1194","congNang":["Hấp thu dấu ấn từ những Cổ giới tan vỡ tại Giới Phần.","Cắm rễ tại Ngũ Hành chi địa để hấp thu Ngũ hành mẫu khí.","Dùng hỗn độn khí và ánh vàng giam cầm, tiêu diệt những người tùy tiện tiếp cận."],"tabs":{"tienTrinh":[{"chuong":"@c1194","loai":"xuất hiện","importance":"normal","giaiDoan":"Tiến hóa thành Thế Giới Thụ","text":"Chuẩn Thế Giới Thụ xuất hiện giữa Giới Phần, xuyên qua các Cổ giới tan vỡ rồi cắm rễ tại Ngũ Hành chi địa để hấp thu năm loại bản nguyên.","anchor":"Phàm là muốn trở thành Thế Giới Thụ, bình thường đều sẽ tới Giới Phần, từ trong một lượng lớn tàn nát Cổ giới rút lấy dấu ấn","phamCap":"Chuẩn Thế Giới Thụ"}]},"nguon":["@c1194"]},{"id":"hoa-dao-chung-cua-huyen-con","name":"Hỏa đạo chủng của Huyền Côn","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Hiếm có","soHuu":["Huyền Côn"],"trangThai":"Bị Huyền Côn quấn giữ","blurb":"Hỏa đạo chủng là một viên Đạo chủng hệ hỏa hiếm có, ẩn trong hang cổ màu đỏ tại Ngũ Hành chi địa. Khi bị kinh động và định bay đi, nó đã bị Huyền Côn dùng ba đạo tiên khí quấn giữ.","detail":"Hỏa đạo chủng vốn ẩn trong một hang cổ màu đỏ tại Ngũ Hành chi địa. Khi Huyền Côn rơi xuống hang, viên Đạo chủng bị kinh động, định bay lên nhưng lập tức bị ba đạo tiên khí của Huyền Côn quấn lấy và khống chế, từ đó rơi vào tay hắn. @c1194","phanLoaiPhu":"Đạo chủng hệ hỏa","dacDiem":"Một viên hỏa đạo chủng hiếm có, có khả năng tự bay đi và từng ẩn trong hang cổ màu đỏ tại Ngũ Hành chi địa.","chuHienThoi":"Huyền Côn","capNhatToi":"@c1194","chuSoHuu":[{"ten":"Huyền Côn","tuChuong":"@c1194","denChuong":"","cachCoDuoc":"Dùng ba đạo tiên khí quấn giữ khi hạt giống định bay khỏi hang cổ.","trangThai":"Đang nắm giữ"}],"tabs":{"tienTrinh":[{"chuong":"@c1194","loai":"đổi chủ","importance":"major","giaiDoan":"Bị Huyền Côn đoạt lấy","text":"Hỏa đạo chủng bị kinh động trong hang cổ màu đỏ và bị ba đạo tiên khí của Huyền Côn quấn giữ.","anchor":"Ai cũng không nghĩ tới, lúc này mới vừa đến đến, thì có người bắt lấy một viên hiếm có hỏa đạo chủng tử","phamCap":"Hiếm có"}]},"nguon":["@c1194"]},{"id":"ngu-hanh-tien-chung","name":"Ngũ hành tiên chủng","cn":"","aliases":["Ngũ hành hạt giống"],"category":"khac","categoryLabel":"Đạo chủng","phamCap":"Tiên chủng hoàn mỹ","soHuu":[],"trangThai":"Chưa được tìm thấy","blurb":"Viên tiên chủng hoàn mỹ được đồn rằng đang được thai nghén tại Ngũ Hành chi địa. Cấp độ của nó có thể sánh với hạt giống mô hình vũ trụ.","detail":"Ngũ hành tiên chủng hội tụ năm loại bản nguyên kim, mộc, thủy, hỏa, thổ và được xem là một trong những Đạo chủng mạnh nhất tại cổ địa. Sau khi tin tức được công bố, nó trở thành mục tiêu tranh đoạt của các học sinh.","phanLoaiPhu":"Đạo chủng Ngũ hành","uyLuc":"Có cấp độ đủ để sánh với hạt giống mô hình vũ trụ.","dacDiem":"Được mô tả là hoàn mỹ không tì vết.","capNhatToi":"@c1194","tabs":{"tienTrinh":[{"chuong":"@c1194","loai":"xuất hiện","importance":"normal","giaiDoan":"Trở thành mục tiêu tranh đoạt","text":"Tin tức về Ngũ hành tiên chủng hoàn mỹ tại cổ địa được công bố, khiến nó trở thành mục tiêu lớn nhất của các học sinh.","anchor":"khu cổ địa này thai nghén một viên Ngũ hành tiên chủng, hoàn mỹ không một tì vết, có thể sánh vai Vũ Trụ mô hình hạt giống","phamCap":"Tiên chủng hoàn mỹ"}]},"nguon":["@c1194"]},{"id":"thuy-dao-hat-giong","name":"Thủy đạo hạt giống","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng","phanLoaiPhu":"Tiên chủng thuộc Thủy đạo","phamCap":"Đạo chủng quý hiếm thuộc Ngũ hành","soHuu":["Yêu Nguyệt"],"trangThai":"Đã được Yêu Nguyệt thu lấy","hinhDang":"Một viên hạt giống xanh lam óng ánh","dacDiem":"Có màu xanh lam óng ánh, phát ra ánh sáng xanh thần thánh và được ví như trái tim của biển.","chuHienThoi":"Yêu Nguyệt","blurb":"Thủy đạo hạt giống là một đạo chủng thuộc Thủy đạo, được Yêu Nguyệt lấy ra sau khi phá mở một ngọn núi linh khí trên Ngũ hành đại lục. Hạt giống xanh lam óng ánh, tỏa thần quang và được ví như trái tim của biển.","detail":"Thủy đạo hạt giống thuộc nhóm báu vật Ngũ hành, vốn nằm bên trong một ngọn núi linh khí trên Ngũ hành đại lục. Yêu Nguyệt đã phá mở ngọn núi và lấy nó; những người chứng kiến không dám tranh đoạt vì e ngại thực lực của nàng. Hạt giống mang màu xanh lam óng ánh, phát ra ánh sáng xanh thần thánh và được ví như trái tim của biển. @c1195","chuSoHuu":[{"ten":"Yêu Nguyệt","tuChuong":"@c1195","denChuong":"","cachCoDuoc":"Phá mở một ngọn núi linh khí rồi lấy hạt giống từ bên trong.","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1195","loai":"đổi chủ","importance":"major","giaiDoan":"Được Yêu Nguyệt thu lấy","text":"Yêu Nguyệt phá mở ngọn núi linh khí và lấy Thủy đạo hạt giống xanh lam từ bên trong.","anchor":"Nàng xé ra một toà linh khí mịt mờ núi lớn, từ ở trong lấy ra một viên lam óng ánh","phamCap":"Đạo chủng quý hiếm thuộc Ngũ hành"}]},"capNhatToi":"@c1195","nguon":["@c1195"]},{"id":"co-thuyen-tien-vien","name":"Cổ thuyền Tiên viện","cn":"","aliases":["Chiến thuyền cổ phủ tiên vụ","Cổ thuyền mang tiên khí"],"category":"phap-bao","categoryLabel":"Chiến thuyền cổ","phamCap":"Không rõ","soHuu":[],"trangThai":"Đang tiến xuống Ngũ hành đại lục","hinhDang":"Một chiếc chiến thuyền cực kỳ cổ xưa, bao phủ bởi tiên vụ","dacDiem":"Được tiên vụ và tiên khí che khuất, có thể di chuyển vô thanh vô tức trong hư không.","congNang":["Di chuyển vô thanh vô tức trong hư không."],"blurb":"Chiến thuyền cổ bí ẩn xuất hiện ngoài Ngũ hành đại lục và lặng lẽ tiến xuống từ hư không Giới Phần.","detail":"Cổ thuyền bị tiên vụ cùng tiên khí che phủ nên trông mơ hồ và thần bí. Người điều khiển và mục đích xuất hiện của nó chưa được tiết lộ.","tabs":{"tienTrinh":[{"chuong":"@c1195","loai":"xuất hiện","importance":"normal","giaiDoan":"Áp sát Ngũ hành đại lục","text":"Cổ thuyền xuất hiện trong hư không ngoài Ngũ hành đại lục rồi âm thầm tiến xuống.","anchor":"Một chiếc chiến thuyền, cực kỳ cổ lão, vô thanh vô tức, chính đang hướng về phía dưới đại lục xuất phát","phamCap":"Không rõ"}]},"capNhatToi":"@c1195","nguon":["@c1195"]},{"id":"dao-chung-kim-loai-cao-cap-nhat","name":"Đạo chủng kim loại cao cấp nhất","cn":"","aliases":[],"category":"khac","categoryLabel":"Đạo chủng thuộc tính Kim","phanLoaiPhu":"Đạo chủng","phamCap":"Gần đạt cực cảnh của đạo chủng kim loại","soHuu":["Thanh Y"],"trangThai":"Vỡ thành phế kim","blurb":"Đạo chủng thuộc tính Kim cao cấp nhất được thai nghén lâu dài trong hồ kim loại trên Ngũ hành đại lục, mang thần văn cùng phù hiệu thiên nhiên và có phẩm chất gần đạt cực cảnh. Sau khi bị Thạch Hạo bắt giữ rồi tặng cho Thanh Y, toàn bộ tinh khí của đạo chủng bị Thanh Nguyệt hấp thu, khiến bản thể vỡ vụn.","detail":"Đạo chủng này được thai nghén lâu dài trong hồ kim loại trên Ngũ hành đại lục. Khi chạy trốn, nó từng hóa thành một chiếc đỉnh nhỏ; sau khi lớp kim loại bên ngoài tan đi, nguyên hình lộ ra là một tinh thể hình thoi gần như trong suốt, mang thần văn và phù hiệu thiên nhiên. Đây là đạo chủng thuộc tính Kim có phẩm chất gần đạt cực cảnh, có thể dùng để dung hợp và chưởng khống sức mạnh thuộc tính Kim. Thạch Hạo bắt được nó rồi tặng Thanh Y, nhưng Thanh Nguyệt đã tự giam giữ và hấp thu toàn bộ tinh khí của đạo chủng, khiến bản thể cuối cùng vỡ vụn. @c1196","hinhDang":"Tinh thể hình thoi gần như trong suốt, từng hóa thành đỉnh nhỏ","nguonGoc":"Được thai nghén lâu dài trong hồ kim loại trên Ngũ hành đại lục","uyLuc":"Có thể giúp người dung hợp chưởng khống sức mạnh thuộc tính Kim.","dacDiem":"Nguyên hình là tinh thể hình thoi gần như trong suốt, bên ngoài từng có một lớp kim loại; mang thần văn và phù hiệu thiên nhiên, phẩm chất gần đạt cực cảnh.","chuHienThoi":"Không còn chủ sở hữu do bản thể đã vỡ","capNhatToi":"@c1196","congNang":["Dùng làm đạo chủng để dung hợp và chưởng khống sức mạnh thuộc tính Kim. @c1196","Có thể hóa thành một chiếc đỉnh nhỏ để chạy trốn."],"chuSoHuu":[{"ten":"Thanh Y","tuChuong":"@c1196","denChuong":"@c1196","cachCoDuoc":"Được Thạch Hạo tặng","trangThai":"Đã mất do tinh khí bị hấp thu và bản thể vỡ vụn"}],"tabs":{"tienTrinh":[{"chuong":"@c1196","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị hấp thu tinh khí","text":"Thạch Hạo bắt được đạo chủng rồi tặng Thanh Y, nhưng Thanh Nguyệt tự giam giữ và hấp thu toàn bộ tinh khí của nó. Bản thể đạo chủng sau đó vỡ thành phế kim.","anchor":"Cuối cùng, răng rắc một tiếng, cái này báu vật vô giá trên đời hạt giống vỡ nát, hóa thành phế kim","phamCap":"Gần đạt cực cảnh của đạo chủng kim loại"}]},"nguon":["@c1196"]},{"id":"thanh-nguyet-cua-thanh-y","name":"Thanh Nguyệt của Thanh Y","cn":"","aliases":[],"category":"khac","categoryLabel":"Tiên chủng","phanLoaiPhu":"Tiên chủng","phamCap":"Tiềm lực được so sánh với mầm non Thế Giới Thụ và hạt giống Ngũ hành","soHuu":["Thanh Y"],"trangThai":"Đang thai nghén sinh cơ","blurb":"Thanh Nguyệt là tiên chủng gắn với Thanh Y, mang hình thái một vòng trăng xanh. Nó có thể giam giữ đạo chủng khác, hấp thu tinh khí bên trong và thai nghén sinh cơ sau khi hấp thu đạo chủng Kim.","detail":"Khi Thanh Y nhận đạo chủng thuộc tính Kim, vòng Thanh Nguyệt tự hiện lên trên đầu nàng, giam giữ đạo chủng này rồi hấp thu toàn bộ tinh khí của nó. Sau lần hấp thu, bên trong Thanh Nguyệt xuất hiện sinh cơ phồn thịnh; Thạch Hạo từ đó nhận định đây chính là tiên chủng của Thanh Y và có khả năng tiếp tục nuốt tinh khí của các loại đạo chủng khác. @c1196","hinhDang":"Một vòng Thanh Nguyệt hiện trên đầu Thanh Y","uyLuc":"Có thể giam giữ đạo chủng Kim và hấp thu toàn bộ tinh khí của nó. @c1196","dacDiem":"Mang hình thái một vòng Thanh Nguyệt; sau khi hấp thu đạo chủng Kim, bên trong xuất hiện sinh cơ phồn thịnh. @c1196","chuHienThoi":"Thanh Y","capNhatToi":"@c1196","congNang":["Giam giữ đạo chủng và hấp thu toàn bộ tinh khí bên trong. @c1196","Thai nghén sinh cơ sau khi hấp thu tinh khí của đạo chủng. @c1196"],"chuSoHuu":[{"ten":"Thanh Y","tuChuong":"@c1196","denChuong":"","cachCoDuoc":"Tiên chủng gắn trực tiếp với Thanh Y","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1196","loai":"khai phong","importance":"major","giaiDoan":"Hé lộ năng lực nuốt đạo chủng","text":"Thanh Nguyệt tự hiện lên, giam giữ đạo chủng Kim rồi hấp thu toàn bộ tinh khí của nó. Sau lần hấp thu, bên trong Thanh Nguyệt bắt đầu thai nghén một luồng sinh cơ phồn thịnh.","anchor":"Cái kia luân Thanh Nguyệt chính là ngươi tiên chủng, có thể nuốt chửng các loại đạo chủng","phamCap":"Tiên chủng có tiềm lực đứng đầu"}]},"nguon":["@c1196"]},{"id":"co-bi-ngu-hanh","name":"Cổ bi Ngũ hành","cn":"","aliases":[],"category":"khac","categoryLabel":"Bia đá thần liệu","phamCap":"Không rõ","soHuu":[],"trangThai":"Tồn tại trên Ngũ hành đại lục","blurb":"Cổ bi được luyện từ Ngũ hành thạch, lưu chuyển thần quang năm màu và ghi lại manh mối Ngũ Ma Phong Thiên Chủng. Nhiều cổ bi tương tự nằm rải rác trên đại lục và đều ghi cùng một nội dung.","detail":"Thân bia chứa năm loại tinh khí bản nguyên. Nội dung trên bia được các trưởng lão dùng để suy đoán quan hệ giữa năm ma, Ngũ hành và một thiên chủng chí cường bị phong tỏa.","vatLieu":"Ngũ hành thạch","dacDiem":"Lưu chuyển thần quang năm màu và chứa năm loại tinh khí bản nguyên.","capNhatToi":"@c1196","nguon":["@c1196"]},{"id":"te-dan-xuong-truyen-tong","name":"Tế đàn xương truyền tống","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bí bảo không gian","phamCap":"Không rõ","soHuu":["Các trưởng lão Thiên Thần Thư Viện"],"trangThai":"Đã được sử dụng","blurb":"Một tòa tế đàn bằng xương được các trưởng lão Thiên Thần Thư Viện hợp lực kích hoạt. Nó có thể xác định tọa độ và truyền tống cả chiến hạm xuyên qua hư không.","detail":"Khi được thúc đẩy, tế đàn phát sáng và làm thời không trở nên hỗn loạn, đưa chiến hạm màu bạc cùng toàn bộ đoàn thám hiểm tới vùng núi lửa Ngũ hành.","hinhDang":"Một tòa tế đàn bằng xương","vatLieu":"Xương cốt","uyLuc":"Có thể truyền tống chiến hạm cùng nhiều người qua khoảng cách xa.","dacDiem":"Cần nhiều trưởng lão hợp lực thúc đẩy và xác định tọa độ.","chuHienThoi":"Các trưởng lão Thiên Thần Thư Viện","capNhatToi":"@c1196","congNang":["Xác định tọa độ và truyền tống chiến hạm xuyên qua hư không @c1196"],"chuSoHuu":[{"ten":"Các trưởng lão Thiên Thần Thư Viện","tuChuong":"@c1196","denChuong":"","cachCoDuoc":"Mang theo để phục vụ cuộc tìm kiếm thiên chủng","trangThai":"Đang sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1196","loai":"dùng","importance":"normal","giaiDoan":"Truyền tống tới vùng núi lửa","text":"Các trưởng lão hợp lực kích hoạt tế đàn xương, xác định tọa độ và truyền tống chiến hạm màu bạc tới vùng núi lửa Ngũ hành.","anchor":"mấy vị trưởng lão lấy ra một toà xương cốt tế đàn, hợp lực thôi thúc, để nó phát sáng","phamCap":"Không rõ"}]},"nguon":["@c1196"]},{"id":"thanh-dong-tien","name":"Thanh đồng tiễn","cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Ngô Thái"],"trangThai":"Đã được sử dụng","blurb":"Loại tên đồng cổ kính được Ngô Thái dùng liên tiếp để săn bắn Thạch Hạo.","detail":"Thanh đồng tiễn mang thế công khó ngăn cản, có thể phá hủy những núi lửa kiên cố được Ngũ Hành bản nguyên tinh khí và thần văn bảo vệ.","phanLoaiPhu":"Tên","hinhDang":"Mũi tên bằng thanh đồng","uyLuc":"Một đợt bắn liên tiếp phá nổ năm ngọn núi lửa tại Ngũ hành đại lục.","dacDiem":"Mang khí tức cổ kính và thế công khó ngăn cản.","chuHienThoi":"Ngô Thái","congNang":["Dùng cùng đồng thai đại cung để công kích mục tiêu ở khoảng cách xa tại @c1197.","Phá hủy núi lửa kiên cố có thần văn bảo vệ tại @c1197."],"chuSoHuu":[{"ten":"Ngô Thái","tuChuong":"@c1197","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1197","loai":"dùng","importance":"normal","giaiDoan":"Bắn phá khu núi lửa","text":"Ngô Thái liên tiếp bắn thanh đồng tiễn về phía Thạch Hạo, khiến nhiều núi lửa kiên cố bị phá hủy.","anchor":"Còn như thanh đồng tiễn, liên tiếp bắn nổ ngũ tòa thật to núi lửa","phamCap":"Không rõ"}]},"capNhatToi":"@c1197","nguon":["@c1197"]},{"id":"dong-thai-dai-cung-cua-ngo-thai","name":"Đồng thai đại cung của Ngô Thái","aliases":["Đồng thai đại cung"],"cn":"","category":"phap-bao","categoryLabel":"Binh khí","phamCap":"Không rõ","soHuu":["Ngô Thái"],"trangThai":"Đang được sở hữu","blurb":"Đại cung bằng đồng do Ngô Thái sử dụng để bắn thanh đồng tiễn về phía Thạch Hạo.","detail":"Ngô Thái dùng đại cung này liên tiếp mở cung săn bắn Thạch Hạo khi hắn đang hóa thành Côn Bằng.","phanLoaiPhu":"Cung","hinhDang":"Đại cung có thai đồng","chuHienThoi":"Ngô Thái","congNang":["Bắn thanh đồng tiễn về phía mục tiêu tại @c1197."],"chuSoHuu":[{"ten":"Ngô Thái","tuChuong":"@c1197","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1197","loai":"dùng","importance":"normal","giaiDoan":"Săn bắn Thạch Hạo","text":"Ngô Thái dùng đồng thai đại cung bắn thanh đồng tiễn vào Thạch Hạo hai lần.","anchor":"cầm trong tay một tấm đồng thai đại cung, tự lọ tên bên trong lấy ra một cây thanh đồng tiễn","phamCap":"Không rõ"}]},"capNhatToi":"@c1197","nguon":["@c1197"]},{"id":"than-niem-toa-hon-tien","name":"Thần niệm tỏa hồn tiễn","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Pháp tiễn","phamCap":"Không rõ","soHuu":["Ngô Thái"],"trangThai":"Đã bắn ra, kết quả cuối chưa rõ","blurb":"Pháp tiễn màu đỏ thẫm được Ngô Thái dùng để truy sát Thạch Hạo. Mũi tên có khả năng khóa nguyên thần của mục tiêu và tự truy kích.","detail":"Mũi tên do một đại nhân vật luyện chế, có thể tiếp nhận thần niệm của người sử dụng để khóa nguyên thần mục tiêu. Sau khi được bắn ra, nó tiếp tục bám theo Thạch Hạo và chưa được xác nhận đã bị hóa giải.","phanLoaiPhu":"Pháp tiễn","hinhDang":"Mũi tên đỏ thẫm","uyLuc":"Có thể khóa nguyên thần và truy kích mục tiêu không ngừng cho tới khi bắn trúng.","dacDiem":"Tiếp nhận thần niệm của người sử dụng để xác định mục tiêu.","chuHienThoi":"Ngô Thái","capNhatToi":"@c1198","congNang":["Khóa chặt nguyên thần của mục tiêu.","Tự truy kích mục tiêu sau khi được bắn ra."],"chuSoHuu":[{"ten":"Ngô Thái","tuChuong":"@c1198","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1198","loai":"dùng","importance":"normal","giaiDoan":"Truy sát Thạch Hạo","text":"Ngô Thái bắn Thần niệm tỏa hồn tiễn để khóa nguyên thần và truy kích Thạch Hạo.","anchor":"có thể khóa chặt nguyên thần của đối phương, không bắn giết không dừng lại","phamCap":"Không rõ"}]},"nguon":["@c1198"]},{"id":"giap-tru-xanh-tham-cua-ngo-thai","name":"Giáp trụ xanh thẳm của Ngô Thái","cn":"","aliases":["Giáp trụ xanh thẳm của tiểu Thiên Vương","Xanh thẳm giáp trụ"],"category":"phap-bao","categoryLabel":"Giáp trụ","phamCap":"Không rõ","soHuu":["Ngô Thái"],"trangThai":"Màn sáng phòng hộ bị phá vỡ","blurb":"Giáp trụ màu xanh thẳm của Ngô Thái, có thể dựng màn sáng xanh nước biển bảo vệ người mặc. Phòng hộ của giáp bị Hỗn Độn quang do Thạch Hạo thi triển phá nát.","detail":"Khi được Ngô Thái thôi thúc bằng bí pháp, giáp trụ dựng lên một màn sáng xanh nước biển và chặn nhiều đòn công kích. Trong cuộc đấu với Thạch Hạo, màn sáng này không chịu nổi sức mạnh âm dương giao hội của Pháp môn Côn Bằng.","phanLoaiPhu":"Giáp phòng hộ","hinhDang":"Giáp trụ màu xanh thẳm","uyLuc":"Có thể dựng màn sáng ngăn chặn nhiều đòn công kích liên tiếp.","dacDiem":"Màn sáng phòng hộ mang màu xanh nước biển.","chuHienThoi":"Ngô Thái","capNhatToi":"@c1198","congNang":["Dựng màn sáng xanh nước biển bảo vệ người mặc."],"chuSoHuu":[{"ten":"Ngô Thái","tuChuong":"@c1198","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đang sở hữu"}],"tabs":{"tienTrinh":[{"chuong":"@c1198","loai":"hư tổn/tu bổ","importance":"normal","giaiDoan":"Phòng hộ bị phá","text":"Giáp trụ dựng màn sáng bảo vệ Ngô Thái nhưng lớp phòng hộ bị Hỗn Độn quang phá nát.","anchor":"trên người hắn xanh thẳm giáp trụ đẩy lên màn ánh sáng đều vỡ nát","phamCap":"Không rõ"}]},"nguon":["@c1198"]},{"id":"mui-ten-dong-thau-bi-che","name":"Mũi tên đồng thau bí chế","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Không rõ","soHuu":["Ngô Thái"],"trangThai":"Đã sử dụng","blurb":"Loạt mũi tên đồng thau bí chế được Ngô Thái dùng để toàn lực bắn giết Thạch Hạo. Mỗi mũi tên đều có sức xuyên phá mạnh, có thể đập vỡ hư không trên đường bay.","detail":"Các mũi tên được bắn bằng đồng thai đại cung của Ngô Thái và không phải sản phẩm do cao thủ Thiên Thần cấp thông thường luyện chế. Khi lao đi, chúng phát ra tiếng rít và phá vỡ trời cao.","phanLoaiPhu":"Mũi tên bí chế","hinhDang":"Mũi tên bằng đồng thau","uyLuc":"Có sức xuyên phá đủ làm vỡ trời cao trên đường bay.","dacDiem":"Được bí chế và dùng thành loạt cùng đồng thai đại cung.","chuHienThoi":"Ngô Thái","capNhatToi":"@c1198","congNang":["Xuyên phá hư không và công kích mục tiêu từ xa."],"chuSoHuu":[{"ten":"Ngô Thái","tuChuong":"@c1198","denChuong":"","cachCoDuoc":"Không rõ","trangThai":"Đã sử dụng"}],"tabs":{"tienTrinh":[{"chuong":"@c1198","loai":"dùng","importance":"normal","giaiDoan":"Bắn giết Thạch Hạo","text":"Ngô Thái dùng đồng thai đại cung bắn liên tiếp các mũi tên đồng thau bí chế về phía Thạch Hạo.","anchor":"mỗi một cái đồng thau tiễn đều phát sinh tiếng ô ô, đập vỡ tan trời cao","phamCap":"Không rõ"}]},"nguon":["@c1198"]},{"id":"hac-sac-thien-mau-cua-ngo-thai","name":"Hắc sắc thiên mâu của Ngô Thái","cn":"","aliases":[],"category":"phap-bao","categoryLabel":"Thần binh","phamCap":"Không rõ","soHuu":["Ngô Thái"],"trangThai":"Bị bẻ gãy","blurb":"Hắc sắc thiên mâu là thần binh màu đen đã thông linh của Ngô Thái, có khả năng chém nứt hư không và bổ đôi núi lửa. Trong cuộc giao chiến với Thạch Hạo, thiên mâu bị hắn tay không kẹp lấy, làm biến dạng rồi bẻ gãy.","detail":"Ngô Thái sử dụng hắc sắc thiên mâu phối hợp với tiên khí biểu kiến do giáp trụ gia trì để liên tục tấn công Thạch Hạo. Binh khí từng chém nứt hư không và bổ đôi núi lửa, nhưng cuối cùng bị Thạch Hạo dùng tay không kẹp lấy lưỡi mâu, khiến nó biến dạng rồi gãy; phần lưỡi sắc sau đó bị ném xuyên vào một ngọn núi lửa. @c1199","phanLoaiPhu":"Thiên mâu","hinhDang":"Thiên mâu màu đen","uyLuc":"Có thể chém nứt hư không và bổ đôi núi lửa. @c1199","dacDiem":"Thần binh màu đen đã thông linh.","chuHienThoi":"Ngô Thái","capNhatToi":"@c1199","congNang":["Chém nứt hư không và phá vỡ, bổ đôi núi lửa. @c1199"],"chuSoHuu":[{"ten":"Ngô Thái","tuChuong":"@c1199","denChuong":"@c1199","cachCoDuoc":"Không rõ","trangThai":"Bị bẻ gãy trong giao chiến"}],"tabs":{"tienTrinh":[{"chuong":"@c1199","loai":"hư tổn/tu bổ","importance":"major","giaiDoan":"Bị phá hủy","text":"Hắc sắc thiên mâu được Ngô Thái dùng để chém nứt hư không và bổ đôi núi lửa, nhưng bị Thạch Hạo tay không bẻ gãy.","anchor":"Thạch Hạo mục quang lạnh lẽo, hai tay chấn động, răng rắc một tiếng, hắn tay không cắt đứt này thần binh!"}]},"nguon":["@c1199"]}]};